// DFIR Error Workflow handler. Fires when any execution in the main workflow errors.
// Sends a friendly notice to the affected user when a chat_id can be recovered from
// the failed execution, and always notifies the admin so backend hiccups are not silent.
const BOT = 'https://api.telegram.org/botCHANGE_ME_DFIR_TG_BOT_TOKEN';
const ADMIN_CHAT = CHANGE_ME_OWNER_CHAT_ID;
const ev = $json || {};
const wfName = (ev.workflow && ev.workflow.name) || 'workflow';
const execId = (ev.execution && ev.execution.id) || '?';
const lastNode = (ev.execution && ev.execution.lastNodeExecuted) || '?';
let errMsg = '';
try { errMsg = String((ev.execution && ev.execution.error && (ev.execution.error.message || ev.execution.error.description)) || ''); } catch(e) {}

// Best-effort: recover the originating chat_id from the trigger payload of the failed run.
let chatId = null;
try {
  const td = ev.execution && ev.execution.executionData && ev.execution.executionData.resultData;
  const run = td && td.runData;
  if (run) {
    for (const k of Object.keys(run)) {
      try {
        const j = run[k][0].data.main[0][0].json;
        const c = (j && (j.callback_query && j.callback_query.message && j.callback_query.message.chat && j.callback_query.message.chat.id))
               || (j && j.message && j.message.chat && j.message.chat.id)
               || (j && j.chat_id);
        if (c) { chatId = Number(c); break; }
      } catch(e) {}
    }
  }
} catch(e) {}

async function send(chat_id, text){
  try { await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true, timeout:12000, body:{ chat_id, text, reply_markup:{ inline_keyboard:[[{ text:'☰ Меню', callback_data:'menu_back' }]] } } }); } catch(e) { console.log('[ErrWF] send failed: ' + (e && e.message)); }
}

if (chatId) {
  await send.call(this, chatId, '⚠️ Сталася тимчасова помилка під час обробки. Спробуйте ще раз або скористайтесь меню.');
}
// admin notice (no internal LLM/model details leaked to users; admin gets diagnostics)
await send.call(this, ADMIN_CHAT, `🛠 Помилка у «${wfName}»\nexec ${execId} · node: ${lastNode}` + (errMsg ? `\n${errMsg.slice(0,300)}` : ''));
return [{ json:{ handled:true, chat_id: chatId, exec: execId } }];

const cb = $('Telegram Trigger').first().json.callback_query;
const uid = String(cb.from.id);
const raw = String(cb.data||'');
let action = raw;
if (raw.startsWith('study_ans_')) action = 'study_ans';
else if (raw.startsWith('study_course_')) action = 'study_course';
else if (raw.startsWith('qa_fb:')) { action = 'qa_fb'; }
else if (raw.startsWith('chatcancel:')) { action = 'chatcancel'; try { await this.helpers.httpRequest({ method:'POST', url:'http://case-maintainer:8787/dfir-cancel', json:true, body:{ token: (raw.split(':')[1]||''), chat_id: cb.message.chat.id } }); } catch(e) {} }
return [{ json: { action, action_raw: raw, chat_id: cb.message.chat.id, callback_id: cb.id, user_id: cb.from.id, is_admin: uid === 'CHANGE_ME_OWNER_CHAT_ID', msg_id: cb.message.message_id } }];

let CFG; try { CFG = $('⚙️ Config').first().json.CONFIG; } catch(e) { throw new Error('CONFIG_MISSING: ⚙️ Config node required'); }
const cb = $('Parse Callback').first().json;
const chatId = cb.chat_id;
const QDRANT = CFG.QDRANT;
const BOT = CFG.BOT;
if (cb.action === 'ram_keys') {
  let _m = '🔑 Немає активного кейсу.';
  try {
    const _ac = (await this.helpers.httpRequest({method:'POST',url:QDRANT+'/collections/kb_sessions/points/scroll',json:true,body:{limit:1,with_payload:true,with_vector:false,filter:{must:[{key:'chat_id',match:{value:Number(chatId)}}]}}}))?.result?.points?.[0]?.payload?.active_case_key;
    if (_ac) {
      const _r = await this.helpers.httpRequest({method:'POST',url:'http://case-maintainer:8787/case-ram-keys',json:true,body:{case_key:_ac,chat_id:String(chatId)},timeout:60000});
      _m = (_r && _r.message) || '✅ Поставлено в чергу.';
    }
  } catch(e) { _m = '⚠️ Не вдалося: ' + String(e).slice(0,120); }
  await this.helpers.httpRequest({method:'POST',url:BOT+'/sendMessage',json:true,body:{chat_id:chatId,text:_m,reply_markup:{inline_keyboard:[[{text:'📁 До кейсу',callback_data:'case_menu'}],[{text:'⬅️ Назад у меню',callback_data:'menu_back'}]]}}});
  return [{json:{done:true,ram_keys:true}}];
}
if (cb.action === 'del_ram') {
  let _m = '🗑 Немає активного кейсу.';
  try {
    const _ac = (await this.helpers.httpRequest({method:'POST',url:QDRANT+'/collections/kb_sessions/points/scroll',json:true,body:{limit:1,with_payload:true,with_vector:false,filter:{must:[{key:'chat_id',match:{value:Number(chatId)}}]}}}))?.result?.points?.[0]?.payload?.active_case_key;
    if (_ac) {
      const _d = await this.helpers.httpRequest({method:'POST',url:'http://case-maintainer:8787/case-delete-ram',json:true,body:{case_key:_ac},timeout:60000});
      _m = (_d && _d.message) || '✅ Готово.';
    }
  } catch(e) { _m = '⚠️ Не вдалося: ' + String(e).slice(0,120); }
  await this.helpers.httpRequest({method:'POST',url:BOT+'/sendMessage',json:true,body:{chat_id:chatId,text:_m,reply_markup:{inline_keyboard:[[{text:'ℹ️ Інфо по кейсу',callback_data:'show_stats'}],[{text:'⬅️ Назад у меню',callback_data:'menu_back'}]]}}});
  return [{json:{done:true,del_ram:true}}];
}
if (cb.action === 'admin_kill_llm') {
  let _msg = '🛑 Завершую завислу LLM…';
  try {
    const _r = await this.helpers.httpRequest({ method:'POST', url:'http://case-maintainer:8787/admin-kill-inference', json:true, body:{}, timeout:30000 });
    const _dn = (_r && _r.done) || {};
    _msg = '✅ Готово.\nПерезапуск моделей: ' + (_dn.agent_restart ? 'так' : 'ні') + '\nСкасовано задач: ' + (_dn.jobs_cancelled || 0) + '\nМоделі завантажаться за ~1-2 хв.';
  } catch(e) { _msg = '⚠️ Не вдалося виконати kill: ' + String(e).slice(0,120); }
  await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true, body:{ chat_id: chatId, text: _msg, reply_markup:{ inline_keyboard:[[{ text:'🔄 Оновити статистику', callback_data:'show_stats' }],[{ text:'⬅️ Назад у меню', callback_data:'menu_back' }]] } } });
  return [{ json:{ done:true, killed:true } }];
}
if (cb.action === 'dl_collector') {
  const _url = 'http://CHANGE_ME_DFIR_LINK_IP:8080/collector';
  let _ver = '';
  try {
    const _cfg = await this.helpers.httpRequest({
      method: 'GET', url: 'http://case-maintainer:8787/config/public-base', json: true });
    const _b = _cfg?.collector_build || {};
    if (_b.version) {
      const _mb = _b.size_bytes ? Math.round(_b.size_bytes / 1048576) : null;
      _ver = 'Версія: ' + _b.version + (_b.built ? ' (зібрано ' + _b.built + ')' : '')
           + (_mb ? '\\nРозмір: ' + _mb + ' МБ' : '') + '\\n\\n';
    }
  } catch (e) {}
  const _txt = '📥 DFIR-колектор (KAPE triage)\\n\\n' + _ver
    + 'Завантаж за посиланням (з машини у твоїй VPN-мережі):\\n' + _url
    + '\\n\\n• Запусти .exe — він САМ попросить права адміністратора (UAC).'
    + '\\n• Обери LIVE або змонтований образ, диск, глибину FAST/FULL.'
    + '\\n• На виході — ZIP, який завантаж боту тут.'
    + '\\n\\nНа сторінці завантаження видно версію, дату й SHA-256 — щоб переконатися, '
    + 'що завантажилось саме те, що ми віддали.';
  await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true, body:{ chat_id: chatId, text:_txt, reply_markup:{ inline_keyboard:[[{ text:'⬅️ Назад у меню', callback_data:'menu_back' }]] } } });
  return [{ json:{ done:true, dl_collector:true } }];
}
// ℹ️ Інфо по кейсу: if a case is active, show per-case info card instead of global stats
try {
  const _active = (await this.helpers.httpRequest({method:'POST',url:QDRANT+'/collections/kb_sessions/points/scroll',json:true,body:{limit:1,with_payload:true,with_vector:false,filter:{must:[{key:'chat_id',match:{value:Number(chatId)}}]}}}))?.result?.points?.[0]?.payload?.active_case_key;
  if (_active) {
    const _ci = await this.helpers.httpRequest({method:'GET',url:'http://case-maintainer:8787/case-info?case_key='+encodeURIComponent(_active),json:true,timeout:15000});
    let _txt2 = (_ci&&_ci.text)||'Інфо недоступне.';
    let _kb2 = [[{text:'📁 До кейсу',callback_data:'case_menu'},{text:'🏠 Меню',callback_data:'menu_back'}]];
    try {
      const _st = await this.helpers.httpRequest({method:'GET',url:'http://case-maintainer:8787/case-storage?case_key='+encodeURIComponent(_active),json:true,timeout:15000});
      if (_st && _st.ok) {
        _txt2 += '\n\n💾 Місце: ' + (_st.total_gb||0) + ' ГБ' + (_st.has_ram ? (' (з них дамп памʼяті ' + (_st.ram_gb||0) + ' ГБ)') : '');
        if (_st.has_ram) _kb2 = [[{text:'🗑 Видалити дамп памʼяті ('+(_st.ram_gb||0)+' ГБ)',callback_data:'del_ram'}]].concat(_kb2);
      }
    } catch(e) {}
    await this.helpers.httpRequest({method:'POST',url:BOT+'/sendMessage',json:true,body:{chat_id:chatId,text:_txt2,reply_markup:{inline_keyboard:_kb2}}});
    return [{json:{done:true,case_info:true}}];
  }
} catch(e) {}



let activeCase = null;
try {
  const sr = await this.helpers.httpRequest({ method:'POST', url: QDRANT + '/collections/kb_sessions/points/scroll', json:true, body:{ limit:1, with_payload:true, filter:{ must:[{ key:'chat_id', match:{ value: chatId } }] } } });
  activeCase = sr?.result?.points?.[0]?.payload?.active_case_key || null;
} catch(e) {}



// AUTHORITATIVE numbers from Postgres via /db-stats (not stale Qdrant) — dynamic + correct
let DB = {};
try { DB = await this.helpers.httpRequest({ method:'GET', url:'http://case-maintainer:8787/db-stats', json:true, timeout:10000 }) || {}; } catch(e) {}
const _casesTxt = (DB.cases_active||0) + (DB.cases_archived ? ' (+' + DB.cases_archived + ' в архіві)' : '');
const lines = [];
lines.push('📊 Статистика системи', '');
lines.push('Для керівництва:');
lines.push(`• Кейсів: ${_casesTxt}`);
lines.push(`• Звітів: ${DB.reports||0}`);
lines.push(`• Логів: ${DB.logs||0}`);
lines.push(`• Документів: ${DB.docs||0}`);
lines.push(`• Індикаторів (IOC): ${DB.iocs||0}`);
lines.push('', 'Технічні обсяги:');
lines.push(`• Chunks звітів (пошук): ${DB.report_chunks||DB.kb_report_chunks||0}`);
lines.push('', 'Стан платформи:');
lines.push(`• Стан: ${DB.platform_ok ? '🟢 Працює' : '🔴 Проблема'}`);
lines.push(`• Сервіси онлайн: ${DB.services_up||0}/${DB.services_total||4}`);
if (activeCase) lines.push('', `📁 Активний кейс: ${String(activeCase).replace(/_/g,' ')}`);

// ── LIVE infra dashboard (GPU / model / queue / jobs) from /admin-live-stats ──
try {
  const ls = await this.helpers.httpRequest({ method:'GET', url:'http://case-maintainer:8787/admin-live-stats', json:true, timeout:8000 });
  lines.push('', '🖥️ Інфраструктура (наживо):');
  for (const g of (ls.gpus||[])) {
    const used = Math.round((g.mem_used_mib||0)/1024*10)/10, tot = Math.round((g.mem_total_mib||0)/1024*10)/10;
    lines.push(`• GPU${g.index}${g.is_display?' 🖥':''}: ${Math.round(g.util_pct||0)}% · ${Math.round(g.temp_c||0)}°C · ${used}/${tot} GB`);
  }
  const mdl = (ls.models||[]).map(m => (typeof m==='string'?m:(m.model||''))).filter(Boolean);
  if (mdl.length) lines.push('• Моделі (готові): ' + mdl.join(', '));
  const q = ls.queue||{};
  lines.push('• Черга LLM: виконується ' + (q.inflight||0) + ', очікує ' + (q.waiters||0) + (q.swapping?' · 🔄 завантаження':''));
  lines.push('• Активних задач: ' + ((ls.jobs||[]).length));
} catch(e) { lines.push('', '🖥️ Інфраструктура: дані недоступні'); }

if (cb.msg_id) { try { await this.helpers.httpRequest({method:'POST',url:BOT+'/deleteMessage',json:true,body:{chat_id:chatId,message_id:cb.msg_id}}); } catch(e) {} }
await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true, body:{ chat_id: chatId, text: lines.join('\n'), reply_markup:{ inline_keyboard:[ [{ text:'🔄 Оновити', callback_data:'show_stats' }], [{ text:'📥 Завантажити колектор', callback_data:'dl_collector' }], [{ text:'⬅️ Назад у меню', callback_data:'menu_back' }] ] } } });
return [{ json:{ done:true, scope:'general' } }];

let CFG; try { CFG = $('⚙️ Config').first().json.CONFIG; } catch(e) { throw new Error('CONFIG_MISSING: ⚙️ Config node required'); }

const chatId = $('Parse Callback').first().json.chat_id;
const userId = $('Parse Callback').first().json.user_id;
const BOT = CFG.BOT;
const QDRANT = CFG.QDRANT;

let activeCase = null;
try {
  const sr = await this.helpers.httpRequest({
    method:'POST', url: QDRANT + '/collections/kb_sessions/points/scroll', json:true,
    body:{ limit:1, with_payload:true, with_vector:false, filter:{ must:[{ key:'chat_id', match:{ value: chatId } }] } }
  });
  activeCase = sr?.result?.points?.[0]?.payload?.active_case_key || null;
} catch(e) {}

const action = String($('Parse Callback').first().json.action || '');
if (action === 'my_cases_menu') {
  const _msgId = $('Parse Callback').first().json.msg_id;
  if (_msgId) { try { await this.helpers.httpRequest({method:'POST',url:BOT+'/deleteMessage',json:true,body:{chat_id:chatId,message_id:_msgId}}); } catch(e) {} }
  await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true, body:{
    chat_id: chatId,
    text:'📁 Мої кейси\n' + (activeCase ? ('🟢 Активний: ' + String(activeCase).replace(/_/g,' ') + '\n') : '⚪ Активний: немає\n') + '\nОберіть дію:',
    reply_markup:{ inline_keyboard:[
      [{text:'📂 Показати кейси', callback_data:'show_cases_list'}],
      [{text:'🆕 Створити новий кейс', callback_data:'create_case'}],
      [{text:'📥 Файли кейсу', callback_data:'files_case'},{text:'🔗 Пересічення звітів', callback_data:'cross_reports'}],
      [{text:'⬅️ Назад у меню', callback_data:'menu_back'}]
    ]}
  }});
  return [{json:{done:true,menu:'my_cases'}}];
}


function canonCaseKey(v){ return String(v||'').trim().replace(/[\s_]+/g,'_').replace(/^_+|_+$/g,'').toLowerCase(); }

async function collectCasesFromCollection(coll){
  const unique = {};
  let offset = null;
  for(let i=0;i<200;i++){
    const body = { limit: 256, with_payload: true, with_vector: false };
    if (offset) body.offset = offset;
    const r = 
await this.helpers.httpRequest({ method:'POST', url: QDRANT + '/collections/' + coll + '/points/scroll', body, json:true });
    const points = r.result?.points || [];
    for (const p of points){
      const payload = p.payload || {};
      const k = payload.case_key || payload.case || payload.case_id;
      if (!k) continue;
      if (['file','kb','unknown','unknown_case','none','null'].includes(String(k).toLowerCase())) continue;
      const ck = canonCaseKey(k);
      if (!unique[ck]) unique[ck] = { case_key: k, case_name: payload.case_name || k };
    }
    offset = r.result?.next_page_offset;
    if (!offset || points.length === 0) break;
  }
  return unique;
}

try {
  // Query cases from PostgreSQL via case-maintainer
  let merged = {};
  try {
    const pgCases = await this.helpers.httpRequest({ method:'GET', url:'http://case-maintainer:8787/cases-list?chat_id=' + encodeURIComponent(chatId), json:true });
    for (const c of (pgCases.cases || [])) {
      const ck = canonCaseKey(c.case_key);
      merged[ck] = { case_key: c.case_key, case_name: c.case_name || c.case_key, created_at: c.created_at || null };
    }
  } catch(e) {}

  // ensure active case is visible even before first upload
  const activeCanon = canonCaseKey(activeCase||'');
  if (activeCase && activeCanon && !Object.values(merged).some(x => canonCaseKey(x.case_key||x.case_name||'')===activeCanon)) {
    merged[activeCanon] = { case_key: activeCase, case_name: activeCase };
  }
  const list = Object.values(merged).sort((x,y)=>(String(y.created_at||'').localeCompare(String(x.created_at||''))) || String(x.case_name).localeCompare(String(y.case_name), 'uk'));

  if (list.length === 0 && !activeCase) {
    await this.helpers.httpRequest({
      method: 'POST', url: BOT + '/sendMessage',
      body: { chat_id: chatId, text: '📭 Немає кейсів. Завантажте звіт!' }, json: true
    });
    return [{ json: { done: true } }];
  }

  const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r2 = Math.random() * 16 | 0;
    return (c === 'x' ? r2 : (r2 & 0x3 | 0x8)).toString(16);
  });
  try {
    const stateResp = await this.helpers.httpRequest({
      method: 'POST', url: QDRANT + '/collections/kb_user_state/points/scroll',
      body: { limit: 1, with_payload: true, filter: { must: [{ key: 'user_id', match: { value: userId } }] } },
      json: true
    });
    const existing = stateResp.result?.points?.[0]?.payload || {};
    await this.helpers.httpRequest({
      method: 'POST', url: QDRANT + '/collections/kb_user_state/points/delete',
      body: { filter: { must: [{ key: 'user_id', match: { value: userId } }] } }, json: true
    });
    await this.helpers.httpRequest({
      method: 'PUT', url: QDRANT + '/collections/kb_user_state/points',
      body: { points: [{ id: uuid, vector: Array(1024).fill(0.001), payload: { ...existing, user_id: userId, cases_list: list } }] },
      json: true
    });
  } catch(e) {}

  const safeList = list.length ? list : (activeCase ? [{case_key:activeCase, case_name:activeCase}] : []);
  const keyboard = safeList.slice(0, 30).map((c, i) => [{
    text: (() => { const isA = activeCase && String(c.case_key)===String(activeCase); const p = isA ? '🟢 ' : '📁 '; const t = p + (c.case_name || c.case_key).replace(/_/g, ' '); return t.length <= 40 ? t : (t.slice(0, 37) + '...'); })(),
    callback_data: 'ci_' + i
  }]);
  keyboard.push([{ text: '⬅️ Назад у меню', callback_data: 'menu_back' }]);

  // 1) First send full text list (so content stays above)
  const fullLines = safeList.map((c, i) => `${i+1}. ${activeCase && String(c.case_key)===String(activeCase) ? '🟢 ' : ''}${(c.case_name || c.case_key).replace(/_/g,' ')}`);
  let chunk = '📄 Кейси (' + list.length + '):\n' + (activeCase ? ('🟢 Активний зараз: ' + String(activeCase).replace(/_/g,' ') + '\n\n') : '\n') ;
  for (const ln of fullLines) {
    if ((chunk + ln + '\n').length > 3800) {
      await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', body:{ chat_id: chatId, text: chunk.trim() }, json:true });
      chunk = '';
    }
    chunk += ln + '\n';
  }
  if (chunk.trim()) {
    await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', body:{ chat_id: chatId, text: chunk.trim() }, json:true });
  }

  // 2) Then send selection buttons as the last message (buttons at bottom)
  await this.helpers.httpRequest({
    method: 'POST', url: BOT + '/sendMessage',
    body: {
      chat_id: chatId,
      text: '👇 Оберіть кейс кнопкою нижче:',
      reply_markup: { inline_keyboard: keyboard }
    },
    json: true
  });

  return [{ json: { done: true } }];
} catch(e) {
  return [{ json: { done: false, error: e.message } }];
}

let CFG; try { CFG = $('⚙️ Config').first().json.CONFIG; } catch(e) { throw new Error('CONFIG_MISSING: ⚙️ Config node required'); }
const chatId=$('Parse Callback').first().json.chat_id; const userId=String($('Parse Callback').first().json.user_id||''); const BOT=CFG.BOT; const QDRANT=CFG.QDRANT;
async function send(text,kb){ return await this.helpers.httpRequest({method:'POST',url:BOT+'/sendMessage',json:true,body:{chat_id:chatId,text,reply_markup:{inline_keyboard:kb}}}); }
if(userId!=='CHANGE_ME_OWNER_CHAT_ID'){ await send('⛔ Видалення дозволено лише адміну.',[[{text:'⬅️ Меню',callback_data:'menu_back'}]]); return [{json:{done:true,denied:true}}]; }
let resp={}; try { resp=await this.helpers.httpRequest({method:'GET',url:'http://case-maintainer:8787/cases-list',json:true,timeout:10000}); } catch(e){ resp={cases:[],error:String(e.message||e)}; }
const list=(resp.cases||[]).filter(c=>c.case_key);
if(!list.length){ await send('📭 Немає кейсів для видалення.',[[{text:'⬅️ Адмін-меню',callback_data:'admin_monitor'}]]); return [{json:{done:true,empty:true}}]; }
