    if (cut < size * 0.5) cut = s.lastIndexOf(' ', size);
    if (cut < 0) cut = size;
    else cut += 1;
    parts.push(s.slice(0, cut).trim());
    s = s.slice(cut).trim();
  }
  if (s) parts.push(s);
  return parts;
