      if (tp.trim().length > 20) fixed.push({ text: tp.trim(), chunk_index: fixed.length, page_num: c.page_num||1 });
    }
  }
  chunks.length = 0;
  for (const x of fixed) chunks.push(x);
  out.chunks_total = chunks.length;
}


if (!chunks.length) {
  out.hard_gate_failed = strict;
  out.gate_stage = 'no_chunks';
  return [{ json: out }];
}

const padVec = (v) => {
  const vv = Array.isArray(v) ? v.slice(0, EMBED_DIM) : [];
  while (vv.length < EMBED_DIM) vv.push(0.0);
  return vv;
};

async function embedOne(prompt) {
  const p = String(prompt || '').slice(0, 2500);
  for (const m of [EMBED_MODEL, EMBED_FALLBACK]) {
    try {
      // Ollama new API (preferred)
      let r = await this.helpers.httpRequest({
        method: 'POST',
        url: EMBED_OLLAMA + '/v1/embeddings',
        body: { model: m, input: p },
        json: true,
        timeout: 180000,
      });
      if (Array.isArray(r?.embeddings) && r.embeddings.length && Array.isArray(r.embeddings[0])) {
        return { ok: true, vec: padVec(r.embeddings[0]), model: m, err: '' };
      }
      // backward compatibility
      r = await this.helpers.httpRequest({
        method: 'POST',
        url: EMBED_OLLAMA + '/v1/embeddings',
        body: { model: m, input: p },
        json: true,
        timeout: 180000,
      });
      if (Array.isArray(r?.embedding) && r.embedding.length) {
        return { ok: true, vec: padVec(r.embedding), model: m, err: '' };
      }
      if (Array.isArray(r?.data?.[0]?.embedding) && r.data[0].embedding.length) {
        return { ok: true, vec: padVec(r.data[0].embedding), model: m, err: '' };
      }
    } catch (e) {
      lastEmbedErr = String(e?.message || e || 'embed_call_failed'); await new Promise(r=>setTimeout(r,300)); // continue to fallback
    }
  }
  return { ok: false, vec: null, model: '', err: (lastEmbedErr || 'embed_failed') };
}

const points = [];
for (const ch of chunks) {
  const er = await embedOne.call(this, ch.text);
  if (!er.ok) {
    out.hard_gate_failed = strict;
    out.gate_stage = 'embed_failed';
    out.embed_error = er.err || '';
    out.embed_attempted = true;
    out.embed_model_used = out.embedding_model || '';
    out.embedded_ok = false;
    out.indexed_ok = false;
    out.embedding_model = '';
    out.embeddings_count = 0;
    return [{ json: out }];
  }
  out.embedded_ok = true;
  out.embeddings_count += 1;
  if (!out.embedding_model) out.embedding_model = er.model;
  points.push({
    id: uuidv4(),
    vector: er.vec,
    payload: {
      text: ch.text,
      chunk_index: ch.chunk_index,
      page_num: ch.page_num,
      total_chunks: chunks.length,
      case_key: caseKey,
      doc_type: docType,
      skill_id: skillId,
      source_file: fileName,
      uploaded_by: userId,
      uploaded_at: timestamp,
