    await this.helpers.httpRequest({ method:'PUT', url: QDRANT + '/collections/kb_artifacts/points', json:true, body:{ points:[art] }, timeout:20000 });
    out.artifact_written = true;
    out.artifact_upload_id = upId;
  } catch(e) {
    out.artifact_written = false;
    out.artifact_error = String(e?.message || e || 'kb_artifacts_write_failed');
