}

return [{ json: out }];

const inData = $input.first().json || {};
const text = String(inData.text || inData.question || inData.body?.text || inData.body?.question || inData.query || inData.body?.query || inData.message?.text || '').trim();
const userId = String(inData.user_id || inData.userId || inData.message?.from?.id || inData.callback_query?.from?.id || '');
const chatId = Number(inData.chat_id || inData.body?.chat_id || inData.chatId || inData.body?.chatId || inData.message?.chat?.id || CHANGE_ME_OWNER_CHAT_ID);
