const strictGroundedIn = !!(inData.strict_grounded === true || inData.body?.strict_grounded === true);
// sanitize pasted chat transcripts (pasted chat logs)
let cleanText = text
  .split(/\n/)
  .filter(l => !/^\s*(operator|dfir-bot),\s*\[/.test(l))
  .filter(l => !/^\s*🔍\s*Шукаю/.test(l))
