// canonicalize common DFIR terms/typos (ua/ru/en variants)
cleanText = cleanText
  .replace(/ амкеш /gi,'amcache')
  .replace(/ am cache /gi,'amcache')
  .replace(/ амкэ?ш /gi,'amcache')
  .replace(/ шимкеш /gi,'shimcache')
  .replace(/ префетч /gi,'prefetch')
  .replace(/ джамп\s*лист /gi,'jumplist')
  .replace(/ юсн /gi,'usn')
  .replace(/ логфайл /gi,'$logfile');

if (cleanText) {
  // if numbered list exists, keep only numbered lines + continuation
  const lines = cleanText.split(/\n/);
  const num = lines.filter(l => /^\s*\d+[\).]/.test(l));
  if (num.length) cleanText = num.join('\n');
}

const qCount = (cleanText.match(/\?/g) || []).length + (cleanText.match(/(^|\n)\s*\d+[\).]/g) || []).length;
const tooMany = qCount >= 8 || text.length > 2500;


// manual IOC capture fallback (user-state based), supports strict and free-form IOC input
try {
  const tg = inData || {};
  const uidRaw = tg.message?.from?.id || tg.callback_query?.from?.id || null;
  const uidStr = String(uidRaw || '');

  let ustate = null;
  if (uidRaw !== null || uidStr) {
    const s1 = await this.helpers.httpRequest({method:'POST',url:'http://qdrant:6333/collections/kb_user_state/points/scroll',json:true,body:{limit:1,with_payload:true,with_vector:false,filter:{must:[{key:'user_id',match:{value:uidRaw}}]}}});
    ustate = s1?.result?.points?.[0]?.payload || null;
    if (!ustate && uidStr) {
      const s2 = await this.helpers.httpRequest({method:'POST',url:'http://qdrant:6333/collections/kb_user_state/points/scroll',json:true,body:{limit:1,with_payload:true,with_vector:false,filter:{must:[{key:'user_id',match:{value:uidStr}}]}}});
      ustate = s2?.result?.points?.[0]?.payload || null;
    }
  }

  const _iocShape = /( (?:ip|domain|url|hash|sha256|sha1|md5|file|filename)\s*:)|(?: (?:\d{1,3}\.){3}\d{1,3} )|(?:https?:\/\/)|(?: [a-fA-F0-9]{32,64} )|(?: (?:[a-zA-Z0-9-]+\.)+[a-zA-Z]{2,} )/i.test(String(text||''));
  if (ustate?.pending_manual_ioc === true && _iocShape) {
    const sess = await this.helpers.httpRequest({method:'POST',url:'http://qdrant:6333/collections/kb_sessions/points/scroll',json:true,body:{limit:1,with_payload:true,with_vector:false,filter:{must:[{key:'chat_id',match:{value:chatId}}]}}});
    const sp = sess?.result?.points?.[0]?.payload || {};
    const activeCase = sp.active_case_key || null;
    if (!activeCase) return [{ json: { text, chat_id: chatId, manual_ioc_handled:true, manual_ioc_error:true, manual_ioc_message:'❌ Немає активного кейсу. Спочатку оберіть кейс.' } }];

    const raw = String(text || '').trim();
    const items = [];
    const typeMap = { hash:'hash_sha256', sha256:'hash_sha256', sha1:'hash_sha1', md5:'hash_md5', ip:'ip', domain:'domain', url:'url', file:'file_name', filename:'file_name' };
    const normType = (t) => typeMap[String(t||'').toLowerCase().trim()] || String(t||'').toLowerCase().trim();
    const add = (t,v) => { const tv=String(v||'').trim(); const tt=normType(t); if (tt && tv) items.push({ioc_type:tt,value:tv}); };

    for (const line of raw.split(/\n+/)) {
      const m = line.match(/^\s*([a-zA-Zа-яА-ЯіІїЇєЄ0-9_\-]+)\s*:\s*(.+)\s*$/);
      if (m) add(m[1], m[2]);
    }

    const rxIp = /\b(?:\d{1,3}\.){3}\d{1,3}\b/g;
    const rxUrl = /https?:\/\/[^\s"'<>]+/gi;
    const rxSha256 = /\b[a-fA-F0-9]{64}\b/g;
    const rxSha1 = /\b[a-fA-F0-9]{40}\b/g;
    const rxMd5 = /\b[a-fA-F0-9]{32}\b/g;
    const rxDomain = /\b(?:[a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}\b/g;
    for (const v of (raw.match(rxUrl) || [])) add('url', v);
    for (const v of (raw.match(rxIp) || [])) add('ip', v);
    for (const v of (raw.match(rxSha256) || [])) add('hash_sha256', v);
    for (const v of (raw.match(rxSha1) || [])) add('hash_sha1', v);
    for (const v of (raw.match(rxMd5) || [])) add('hash_md5', v);
    for (const v of (raw.match(rxDomain) || [])) {
      const d = String(v).toLowerCase();
      if (!/^\d+\.\d+\.\d+\.\d+$/.test(d) && !d.startsWith('http')) add('domain', d);
    }

    const uniq=[]; const seen=new Set();
    for (const it of items) { const k=`${it.ioc_type}:${String(it.value).toLowerCase()}`; if(seen.has(k)) continue; seen.add(k); uniq.push(it); }
    if (!uniq.length) return [{ json: { text, chat_id: chatId, manual_ioc_handled:true, manual_ioc_error:true, manual_ioc_message:'❌ Не знайшов IOC у повідомленні. Надішліть `тип:значення` або вставте список IOC.', source_cases:['manual_ioc'], user_id: userId } }];

    const points = uniq.slice(0,120).map(it => ({ id:'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&0x3|0x8)).toString(16)}), vector:Array(1024).fill(0.001), payload:{ case_key:activeCase, ioc_type:it.ioc_type, value:it.value, source:'manual', source_file:'manual_input', doc_type:'manual', uploaded_by:uidStr||String(uidRaw||''), uploaded_at:new Date().toISOString() } }));
    await this.helpers.httpRequest({method:'PUT',url:'http://qdrant:6333/collections/kb_iocs/points',json:true,body:{points}});

    try {
      const prev=ustate||{};
      const idu='xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&0x3|0x8)).toString(16)});
      await this.helpers.httpRequest({method:'POST',url:'http://qdrant:6333/collections/kb_user_state/points/delete',json:true,body:{filter:{must:[{key:'user_id',match:{value:uidStr||uidRaw}}]}}});
      await this.helpers.httpRequest({method:'PUT',url:'http://qdrant:6333/collections/kb_user_state/points',json:true,body:{points:[{id:idu,vector:Array(1024).fill(0.001),payload:{...prev,user_id:uidStr||uidRaw,pending_manual_ioc:false,last_manual_ioc_result:`saved:${uniq.length}`,updated_at:new Date().toISOString()}}]}});
    } catch(e) {}

    return [{ json: { text, chat_id: chatId, manual_ioc_handled:true, manual_ioc_saved:true, manual_ioc_message:`✅ Додано IOC: ${uniq.length}\nКейс: ${String(activeCase).replace(/_/g,' ')}`, source_cases:['manual_ioc'], user_id: userId } }];
  }
} catch(e) {}

const isAliasCommand = /^(?:\s*alias |\s*alias_import |\s*#)/i.test(text);
if (isAliasCommand) {
  return [{ json: { text, chat_id: chatId, q_count: qCount, too_many_questions: tooMany, source: inData.source || 'telegram_or_webhook', alias_hits: [] } }];
}


// alias/term normalization via kb_terms
let normalized = cleanText || text;
let aliasHits = [];
try {
  const q = String(text || '').toLowerCase();
  const tr = await this.helpers.httpRequest({
    method:'POST', url: 'http://qdrant:6333/collections/kb_terms/points/scroll', json:true,
    body:{ limit: 512, with_payload:true, with_vector:false }
  });
  const pts = tr?.result?.points || [];
  for (const p of pts) {
    const pl = p.payload || {};
    const trigger = String(pl.trigger || '').toLowerCase().trim();
    const canon = String(pl.canonical || '').trim();
    const aliases = String(pl.aliases || '').toLowerCase().split(',').map(s=>s.trim()).filter(Boolean);
    if (!canon) continue;
    const keys = [trigger, ...aliases].filter(Boolean);
    for (const k of keys) {
      if (k && q.includes(k)) {
        aliasHits.push({ key:k, canonical:canon });
      }
    }
  }
  if (aliasHits.length) {
    const uniq = [...new Set(aliasHits.map(a=>a.canonical))];
    // keep user query intact; pass normalized terms separately
    normalized = cleanText || text;
  }
} catch(e) {}


const normalized_terms = [...new Set((aliasHits||[]).map(a=>a.canonical).filter(Boolean))];
const coreTerms=[];
const tl=String(cleanText||text||'').toLowerCase();
const termMap=[
 ['amcache',/(^|\W)amcache(\W|$)|амкеш|амкэ?ш/],
 ['prefetch',/(^|\W)prefetch(\W|$)|префетч/],
 ['shimcache',/(^|\W)shimcache(\W|$)|шимкеш|appcompat/],
 ['mft',/(^|\W)mft(\W|$)|мфт/],
 ['usn',/(^|\W)usn(\W|$)|\$j|journal|юсн/],
 ['$logfile',/\$logfile|logfile|логфайл/],
 ['srum',/(^|\W)srum(\W|$)/],
 ['jumplist',/(^|\W)jumplist(\W|$)|джамп\s*лист/],
 ['evtx',/(^|\W)evtx(\W|$)|event log/],
 ['powershell',/(^|\W)powershell(\W|$)|павершел|повершел/]
];
for (const [name,rx] of termMap){ if (rx.test(tl)) coreTerms.push(name); }
for (const t of coreTerms){ if (!normalized_terms.includes(t)) normalized_terms.push(t); }


let deterministic_answer = '';
const ql = String(normalized||cleanText||text||'').toLowerCase();
if (/amcache|амкеш|амкэ?ш/.test(ql)) {
  deterministic_answer = 'Amcache — це артефакт Windows (Application Compatibility Cache database), який зберігає відомості про запускані/встановлені виконувані файли.\nУ DFIR використовується для підтвердження факту наявності та часто виконання файлу (path, hash, first/last seen, metadata), але не завжди дає повний процесний контекст як Security/Sysmon події.\nПрактично: Amcache добре підсилює execution-гіпотезу разом із 4688/4104/Prefetch.';
}
if (/prefetch|префетч/.test(ql)) {
  deterministic_answer = 'Prefetch — артефакт Windows, що фіксує факт запуску програми (exe), лічильник запусків і часові мітки. У DFIR застосовується для підтвердження execution та таймлайну запусків.';
}
return [{ json: { text: (normalized||cleanText||text), normalized_terms, deterministic_answer, chat_id: chatId, user_id: userId, q_count: qCount, too_many_questions: tooMany, source: inData.source || 'telegram_or_webhook', alias_hits: aliasHits, document_id: incomingDocId, file_name: incomingDocId, strict_grounded: strictGroundedIn } }];

let CFG; try { CFG = $('⚙️ Config').first().json.CONFIG; } catch(e) { throw new Error('CONFIG_MISSING: ⚙️ Config node required'); }

// ═══ Hybrid RAG: vector + keyword | case-scoped or global | always + skill ═══
const input = $input.first().json;
const chatId = input.chat_id;
const session = input.session || {};
