    });
  } catch(e) {}
}


// Quote mode: reuse last contexts
if (input.use_last_contexts && session.last_contexts) {
  return [{ json: { query: input.text, chat_id: chatId,
    contexts: session.last_contexts, source_cases: session.last_sources || [], session } }];
}

const query = input.enriched_query || input.text;
const strictDocIntent = /(по\s+цій\s+книзі|в\s+цій\s+книзі|у\s+цій\s+книзі|тільки\s+по\s+цій\s+книзі|this\s+book|this\s+document|only\s+this\s+document)/i.test(String(query||''));
const explicitDoc = String(input.document_id || input.file_name || '').trim();
const lastSrcPdf = Array.isArray(session.last_sources) ? String((session.last_sources.find(s=>/\.pdf/i.test(String(s)))||'')).replace(/#.*$/,'').trim() : '';
const stickyDoc = String(session.active_doc_file || '').trim();
const selectedDocId = explicitDoc || (strictDocIntent ? (stickyDoc || lastSrcPdf) : '');
const strictDocMode = !!selectedDocId;
const strictGrounded = !!(strictDocMode || input.strict_grounded === true);
const normTerms = Array.isArray(input.normalized_terms) ? input.normalized_terms : [];
const queryForSearch = [query, ...(normTerms.slice(0,5))].join(' ').trim();
const ql = String(query||'').toLowerCase();
const caseSummaryIntent = /(що\s+було\s+в\s+цьому\s+кейс(і|у)|підсум(уй|ок)\s+кейс|що\s+стал(о|ося)\s+в\s+кейс|summary\s+of\s+case|case\s+summary)/i.test(ql);
const conceptualMode = /(як|чим|порядок|playbook|метод|крок|workflow|kape|zimmerman|eric)/i.test(ql);
const isGeneralCmdQ = /\bod\s+-c\b|\bgrep\b|\bawk\b|\bsed\b|\bcut\b|\bsort\b|\buniq\b|\btr\b|\bxxd\b|\bhexdump\b|\bstrings\b|\bкоманда\b|what\s+does\s+.*\s+do/i.test(ql);
const discoverIntent = /(які\s+є\s+кейс|які\s+є\s+звіт|де\s+згаду|знайд[иі]\s+кейс|знайд[иі]\s+звіт|which\s+cases|which\s+reports|where\s+mentioned)/i.test(ql) && !strictDocMode;

const qLower = String(query || '').toLowerCase();
const factMode = /(sha256|sha1|md5|хеш|hash|ip|ipv4|домен|domain|url|файл|file_name|ioc)/i.test(qLower)
  || / (?:\d{1,3}\.){3}\d{1,3} /.test(qLower)
  || / [a-f0-9]{32} | [a-f0-9]{40} | [a-f0-9]{64} /i.test(qLower);
const activeSkill   = session.active_skill   || null;
const activeCaseKey = session.active_case_key || null;
const caseFollowupStrict = !!(activeCaseKey && (input.mode==='follow_up' || /детальніше|докладніше|розпиши|поясни|розкрий|продовж/i.test(String(input.text||''))) && session.last_contexts && session.last_contexts.length>80);

await setStage('🔍 Шукаю...... (RAG)');

// Get embedding
let embedding;
try {
  const er = await this.helpers.httpRequest({
    method: 'POST', url: OLLAMA + '/v1/embeddings',
    body: { model: EMBED_MODEL, input: queryForSearch }, json: true, timeout: 30000
  });
  embedding = (er.data && er.data[0] && er.data[0].embedding) ? er.data[0].embedding : er.embedding;
} catch(e) {
  return [{ json: { query, chat_id: chatId, contexts: 'ERROR: ' + e.message, source_cases: [], session } }];
}
if (!Array.isArray(embedding)) {
  return [{ json: { query, chat_id: chatId, contexts: 'ERROR: No embedding', source_cases: [], session } }];
}
const textCollection = (EMBED_MODEL === 'embed-8b') ? (CFG.TEXT_COLL_PRIMARY || 'kb_text_qwen3e8b_v1') : (CFG.TEXT_COLL_FALLBACK || 'kb_text_bgem3_v1');
const docMust = strictDocMode ? [{ key:'source_file', match:{ value:selectedDocId } }] : [];

// ─ Build search plan ─────────────────────────────────────────────────────────
// Layer 1: case-specific (if active case → filter kb_reports + kb_logs)
// Layer 2: always kb_kb_chunks_full
// Layer 3: active skill collection (if set)
// Layer 4: global kb_reports (no filter, if no active case OR low score)

const searchTasks = [];

if (activeCaseKey && (caseSummaryIntent || caseFollowupStrict)) {
  // STRICT case mode for "what happened in this case" queries
  searchTasks.push({ coll: 'kb_reports', filter: { must: [{ key: 'case_key', match: { value: activeCaseKey } }] }, limit: 14, label: '📁' });
  searchTasks.push({ coll: 'kb_logs',    filter: { must: [{ key: 'case_key', match: { value: activeCaseKey } }] }, limit: 10, label: '📋' });
} else {
  // default mixed mode
  searchTasks.push({ coll: textCollection, filter: (docMust.length?{must:docMust}:null), limit: 10, label: '📚' });
  searchTasks.push({ coll: 'kb_kb_core', filter: null, limit: 6, label: '🧠' });
  searchTasks.push({ coll: 'kb_kb_secondary', filter: null, limit: 3, label: '📚' });
  searchTasks.push({ coll: 'kb_memory', filter: null, limit: 3, label: '🧷' });

  if (activeCaseKey) {
    searchTasks.push({ coll: 'kb_reports', filter: { must: [{ key: 'case_key', match: { value: activeCaseKey } }] }, limit: 8, label: '📁' });
    searchTasks.push({ coll: 'kb_logs',    filter: { must: [{ key: 'case_key', match: { value: activeCaseKey } }] }, limit: 5, label: '📋' });
  } else {
    searchTasks.push({ coll: 'kb_reports', filter: null, limit: 4, label: '📄' });
    searchTasks.push({ coll: 'kb_logs',    filter: null, limit: 2, label: '📋' });
  }

  if (!activeCaseKey) {
    searchTasks.push({ coll: textCollection, filter: (docMust.length?{must:docMust}:null), limit: 3, label: '📚' });
  }

  if (conceptualMode) {
    searchTasks.unshift({ coll: 'kb_kb_core', filter: null, limit: 8, label: '🧠' });
    searchTasks.unshift({ coll: 'kb_kb_secondary', filter: null, limit: 4, label: '📚' });
  }
  if (activeSkill) {
    const skillColl = activeSkill.startsWith('n8n_skills_') || activeSkill.startsWith('kb_skills_')
      ? activeSkill
      : 'kb_skills_' + activeSkill;
    searchTasks.push({ coll: skillColl, filter: null, limit: 4, label: '🎯' });
  }
}

if (isGeneralCmdQ) {
  // hard route for command questions: use only KB/skills, skip case reports/logs
  searchTasks.length = 0;
  searchTasks.push({ coll: 'kb_kb_core', filter: null, limit: 8, label: '🧠' });
  searchTasks.push({ coll: 'kb_kb_secondary', filter: null, limit: 6, label: '📚' });
  searchTasks.push({ coll: textCollection, filter: (docMust.length?{must:docMust}:null), limit: 12, label: '📚' });
  searchTasks.push({ coll: textCollection, filter: (docMust.length?{must:docMust}:null), limit: 4, label: '📚' });
  if (activeSkill) {
    const skillColl = activeSkill.startsWith('n8n_skills_') || activeSkill.startsWith('kb_skills_')
      ? activeSkill
      : 'kb_skills_' + activeSkill;
    searchTasks.push({ coll: skillColl, filter: null, limit: 6, label: '🎯' });
  }
}

// ─ Vector search ─────────────────────────────────────────────────────────────
let vectorResults = [];
const scoreBoost = (coll) => {
  if (!conceptualMode) return 0;
  if (coll === 'kb_kb_core') return 0.35;
  if (coll === 'kb_kb_secondary') return 0.2;
  if (coll === 'kb_reports') return -0.15;
  return 0;
};
for (const task of searchTasks) {
  try {
    const body = { vector: embedding, limit: task.limit, with_payload: true };
    if (task.filter) body.filter = task.filter;
    const resp = await this.helpers.httpRequest({
      method: 'POST', url: QDRANT + '/collections/' + task.coll + '/points/search',
      body, json: true, timeout: 15000
    });
    vectorResults = vectorResults.concat(
      (resp.result || []).map(r => ({ ...r, score: (Number(r.score||0)+scoreBoost(task.coll)), _coll: task.coll, _label: task.label, _type: 'vec' }))
    );
  } catch(e) {}
}

// ─ Keyword fallback ───────────────────────────────────────────────────────────
let keywordResults = [];
const stop = new Set(['які','є','чи','де','по','про','в','у','на','що','це','цей','ця','ці','було','кейс','кейси','звіт','звіти','згадується','згадується?','which','cases','reports','where']);
const rawWords = queryForSearch.toLowerCase().replace(/[^\p{L}\p{N}._:-]+/gu,' ').split(/\s+/).filter(Boolean);
const contentWords = rawWords.filter(w => w.length > 2 && !stop.has(w));
const keywords = [...new Set([...contentWords.slice(0,5), ...(contentWords.length ? [contentWords[contentWords.length-1]] : [])])].slice(0,6);
if (keywords.length > 0) {
  const kw = keywords.join(' ');
  const kwColls = activeCaseKey
    ? [{ coll: 'kb_reports', filter: { must: [{ key: 'case_key', match: { value: activeCaseKey } }, { key: 'text', match: { text: kw } }] } }]
    : [{ coll: 'kb_reports', filter: { must: [{ key: 'text', match: { text: kw } }] } },
       { coll: textCollection,    filter: { must: [...docMust, { key: 'text', match: { text: kw } }] } }];
  for (const task of kwColls) {
    try {
      const resp = await this.helpers.httpRequest({
        method: 'POST', url: QDRANT + '/collections/' + task.coll + '/points/scroll',
        body: { limit: 3, with_payload: true, with_vector: false, filter: task.filter },
        json: true, timeout: 10000
      });
      keywordResults = keywordResults.concat(
        (resp.result?.points || []).map(r => ({ payload: r.payload, score: 0.45, _coll: task.coll, _label: '🔤', _type: 'kw' }))
      );
    } catch(e) {}
  }
}


// ─ Discover layer (case/report names + metadata) for global library queries ─
let discoverResults = [];
if (!activeCaseKey && discoverIntent && keywords.length) {
  try {
    const terms = keywords.slice(0,6);
    const scoreTerm = (txt) => {
      const s = String(txt||'').toLowerCase();
      let c = 0;
      for (const t of terms) if (t && s.includes(t)) c += 1;
      return c;
    };

    // reports by file name/case_key/text
    try {
      const rr = await this.helpers.httpRequest({ method:'POST', url: QDRANT + '/collections/kb_reports/points/scroll', body:{ limit: 300, with_payload:true, with_vector:false }, json:true, timeout:12000 });
      for (const p of (rr?.result?.points || [])) {
        const pl = p.payload || {};
        const s1 = scoreTerm(pl.source_file) + scoreTerm(pl.case_key) + scoreTerm(String(pl.text||'').slice(0,800));
        if (s1 > 0) discoverResults.push({ payload: pl, score: 0.95 + Math.min(0.04*s1,0.2), _coll:'kb_reports', _label:'📄', _type:'discover' });
      }
    } catch(e) {}

    // case metadata from kb_cases
    try {
      const rc = await this.helpers.httpRequest({ method:'POST', url: QDRANT + '/collections/kb_cases/points/scroll', body:{ limit: 200, with_payload:true, with_vector:false }, json:true, timeout:12000 });
      for (const p of (rc?.result?.points || [])) {
        const pl = p.payload || {};
        const meta = [pl.case_key, pl.kind, pl.brief_text, ...(Array.isArray(pl.source_reports)?pl.source_reports:[])].join(' ');
        const s2 = scoreTerm(meta);
        if (s2 > 0) discoverResults.push({ payload: { ...pl, source_file: pl.case_key || 'kb_cases' }, score: 1.05 + Math.min(0.04*s2,0.2), _coll:'kb_cases', _label:'🗂', _type:'discover' });
      }
    } catch(e) {}
  } catch(e) {}
}

// ─ IOC fact lookup (kb_iocs) ───────────────────────────────────────────────
let iocResults = [];
if (factMode) {
  try {
    const must = [];
    if (activeCaseKey) must.push({ key: 'case_key', match: { value: activeCaseKey } });
    const iocResp = await this.helpers.httpRequest({
      method: 'POST',
      url: QDRANT + '/collections/kb_iocs/points/scroll',
      body: { limit: 120, with_payload: true, with_vector: false, filter: must.length ? { must } : undefined },
      json: true, timeout: 12000
    });
    const points = iocResp.result?.points || [];
    const kw = qLower.replace(/[^\p{L}\p{N}._:-]+/gu,' ').split(/\s+/).filter(Boolean);
    const scoreIoc = (pl) => {
      const v = String(pl?.ioc_value || '').toLowerCase();
      const t = String(pl?.ioc_type || '').toLowerCase();
      let s = 0;
      for (const k of kw) if (k && (v.includes(k) || t.includes(k))) s += 1;
      if (/sha256|sha1|md5|hash|хеш/.test(qLower) && t.includes('hash')) s += 2;
      if (/(^| )ip( |v4)|адрес|ip/.test(qLower) && t.includes('ip')) s += 2;
      if (/домен|domain|url/.test(qLower) && (t==='domain' || t==='url')) s += 2;
      if (/файл|file/.test(qLower) && t==='file_name') s += 2;
      return s;
    };
    iocResults = points.map(p=>({ payload:p.payload, score: scoreIoc(p.payload), _coll:'kb_iocs', _label:'🧷', _type:'ioc' }))
      .filter(r=>r.score>0)
      .sort((a,b)=>b.score-a.score)
      .slice(0,20);
  } catch(e) {}
}


// ─ Lexical rescue for core DFIR terms (pre-merge) ───────────────────────────
try {
  const qx = String(queryForSearch||'').toLowerCase();
  const keyTerms = [];
  if (/(^|\W)mft(\W|$)|мфт/.test(qx)) keyTerms.push('mft');
  if (/(^|\W)usn(\W|$)|journal|\$j/.test(qx)) keyTerms.push('usn');
  if (/\$logfile|logfile/.test(qx)) keyTerms.push('$logfile');
  if (keyTerms.length) {
    for (const t of keyTerms) {
      const rr = await this.helpers.httpRequest({
        method:'POST',
        url: QDRANT + '/collections/' + textCollection + '/points/scroll',
        body:{ limit: 12, with_payload:true, with_vector:false, filter:{ must:[...docMust,{ key:'text', match:{ text:t } }] } },
        json:true, timeout:12000
      });
      const pts = rr?.result?.points || [];
      keywordResults = keywordResults.concat(pts.map(p => ({ payload:p.payload, score: 0.92, _coll:textCollection, _label:'📚', _type:'kw-rescue' })));
    }
  }
} catch(e) {}

// ─ Merge + dedup ─────────────────────────────────────────────────────────────
const seen = new Set();
let all = [...discoverResults, ...iocResults, ...vectorResults, ...keywordResults].filter(r => {
  const key = (r.payload?.text || '').slice(0, 100);
  if (seen.has(key)) return false;
  seen.add(key); return true;
}).sort((a, b) => (b.score || 0) - (a.score || 0)).slice(0, 8);

const modeInfo = activeCaseKey
  ? `📁 Кейс: ${activeCaseKey.replace(/_/g,' ')}`
  : '🌍 Глобальний пошук';
const skillInfo = activeSkill ? ` | 🎯 ${activeSkill}` : '';

await setStage('🔍 Шукаю.......... (LLM)');

const contexts = all.map(r => {
  const src  = r.payload?.source_file || r._coll;
  const page = r.payload?.page_num ? ` [ст.${r.payload.page_num}]` : '';
  if (r._type === 'discover') {
    const nm = r.payload?.source_file || r.payload?.case_key || 'unknown';
    const br = String(r.payload?.brief_text || '').slice(0,220);
    return `${r._label}[DISCOVER] ${nm}${br ? ('\n' + br) : ''}`;
  }
  if (r._type === 'ioc') {
    const t = r.payload?.ioc_type || 'ioc';
    const v = r.payload?.ioc_value || r.payload?.value || '';
    const ev = r.payload?.evidence_json ? ` | ev: ${String(r.payload.evidence_json).slice(0,180)}` : '';
    return `${r._label}[IOC/${t}] ${v}${ev}`;
  }
  return `${r._label}[${src}${page}]\n${(r.payload?.text || '')}`;
}).join('\n---\n');

const candidateSources = all
  .filter(r => (typeof r.score === 'number' ? r.score >= 0.45 : true))
  .map(r => ({ src: r.payload?.source_file, page: r.payload?.page_num || null, chunk: (r.payload?.chunk_index ?? null), score: r.score || 0 }));
const seenSrc = new Set();
let sourceCases = [];
for (const s of candidateSources) {
  if (!s.src) continue;
  const key = `${s.src}${s.page ? ('#p'+s.page) : ''}`;
  if (seenSrc.has(key)) continue;
  seenSrc.add(key);
  sourceCases.push(s.page ? `${s.src}#p${s.page}` : (s.chunk !== null && s.chunk !== undefined ? `${s.src}#chunk${s.chunk}` : s.src));
}
if (!sourceCases.length) {
  sourceCases = [...new Set(all.map(r => { const src=r.payload?.source_file; const pg=r.payload?.page_num; const ch=r.payload?.chunk_index; return src ? (pg ? `${src}#p${pg}` : (ch!==undefined&&ch!==null ? `${src}#chunk${ch}` : src)) : ''; }).filter(Boolean))];
}
const finalSources = strictDocMode ? sourceCases.filter(s=>String(s).startsWith(selectedDocId)) : (isGeneralCmdQ ? sourceCases.filter(s => !/(drain_Crypto_Analis|case_58|case|report)/i.test(String(s))) : sourceCases);

// Top-3 book sources by relevance (PDF only), dedup by file name
const bookScore = new Map();
for (const r of all) {
  const sf = String(r?.payload?.source_file || '').trim();
  if (!sf || !/\.pdf$/i.test(sf)) continue;
  const sc = Number(r?.score || 0);
  if (!bookScore.has(sf) || sc > bookScore.get(sf)) bookScore.set(sf, sc);
}
const sourceBooksTop3 = [...bookScore.entries()]
  .sort((a,b)=>b[1]-a[1])
  .slice(0,3)
  .map(([source,score]) => ({ source, score: Number(score.toFixed(3)) }));

if (activeCaseKey && (caseSummaryIntent || caseFollowupStrict)) {
  const onlyCase = all.filter(r => String(r?._coll||'')==='kb_reports' || String(r?._coll||'')==='kb_logs');
  const hasUseful = onlyCase.length > 0 && String(contexts||'').trim().length > 80;
  if (!hasUseful) {
    const msg = `Недостатньо релевантних даних у активному кейсі (${String(activeCaseKey).replace(/_/g,' ')}). Уточніть запит або перевірте індексацію звіту.`;
    return [{ json: { query: input.text, chat_id: chatId, contexts: msg, source_cases: [], session, search_mode: `📁 Кейс: ${activeCaseKey.replace(/_/g,' ')}` } }];
  }
}

return [{ json: {
  query: input.text, chat_id: chatId,
  contexts: contexts.substring(0, 5000) || 'Нічого не знайдено',
  source_cases: (finalSources.length ? finalSources : sourceCases), session,
  strict_doc_mode: strictDocMode,
  strict_grounded: strictGrounded,
  selected_doc_id: selectedDocId,
  retrieval_debug: { query: queryForSearch, scope: strictDocMode?'document_id':'global', selected_doc_id:selectedDocId, retrieved_doc_ids:[...new Set(all.map(r=>String(r?.payload?.source_file||'').trim()).filter(Boolean))], top_scores: all.slice(0,8).map(r=>Number((r.score||0).toFixed(3))) },
  search_mode: modeInfo + skillInfo,
  search_stats: { discover: discoverResults.length, ioc: iocResults.length, vec: vectorResults.length, kw: keywordResults.length, total: all.length, fact_mode: factMode },
  discover_hits: discoverResults.slice(0,12).map(r => ({source: r.payload?.source_file || r.payload?.case_key || '', case_key: r.payload?.case_key || '', kind: r.payload?.kind || '', score: r.score || 0})),
  source_books_top3: sourceBooksTop3
} }];

const input = $input.first().json;
const query = String(input.query || '').trim();
const chatId = input.chat_id;
const contexts = String(input.contexts || '');
const sourceCases = input.source_cases || [];
const session = input.session || {};
const searchMode = input.search_mode || '';
const strictGrounded = !!input.strict_grounded;
const strictDocMode = !!input.strict_doc_mode;
const selectedDocId = String(input.selected_doc_id || '').trim();
if (strictGrounded && /(event\s*id|5156|5157)/i.test(query) && !/(5156|5157)/.test(contexts)) {
  return [{json:{chat_id:chatId,answer:'Не знайдено в цьому документі',query,contexts,source_cases:(strictDocMode&&selectedDocId?[selectedDocId]:sourceCases),session:input.session||{},strict_grounded:true,selected_doc_id:selectedDocId}}];
}
const QDRANT='http://qdrant:6333';
let CFG; try { CFG = $('⚙️ Config').first().json.CONFIG; } catch(e) { throw new Error('CONFIG_MISSING: ⚙️ Config node required'); }
const LLM_OPENAI=CFG.OLLAMA+'/v1/chat/completions';
const LLM_MODEL = CFG.LLM_MODEL || 'gpt-oss-120b-heretic-v2'; // FIX: was hardcoded, caused 400 when 2 models loaded

// SINGLE SOURCE OF TRUTH: route general (no active case) free-text Q&A to the backend intent engine,
// which LLM-classifies the question and shapes the answer (list / brief / deep / definition / facts).
// Additive + fail-safe: on any error or empty result, fall through to the legacy logic below.
try {
  const _ac = (session && (session.active_case_key || session.activeCase)) || '';
  if (!strictDocMode && !_ac && query && query.trim().length > 2) {
    const _br = await this.helpers.httpRequest({ method:'POST', url:'http://case-maintainer:8787/dfir-ask', json:true, timeout:120000, body:{ question: query, global:true, live:true, chat_id: chatId } });
    if (_br && _br.ok && (_br.status === 'processing' || _br.source === 'global_live')) {
      return [];  // live: backend owns delivery (progress card + answer)
    }
  }
} catch(e) {}


const dottedRaw = (query.match(/(?:\d{1,3}\.){3}\d{1,3}|\b[\w-]+\.[\w.-]+\b/)||[])[0] || '';
const dotted = /^\d{2}\.\d{2}\.\d{4}$/.test(dottedRaw) ? '' : dottedRaw;
const hashToken = (query.match(/\b[a-fA-F0-9]{64}\b|\b[a-fA-F0-9]{40}\b|\b[a-fA-F0-9]{32}\b/)||[])[0] || '';
const token = dotted || hashToken;

if (false && input.deterministic_answer && String(input.deterministic_answer).trim()) {
  const ans = String(input.deterministic_answer).trim();
  return [{json:{chat_id:chatId,answer:ans+'\n\nSource: kb_terms',query,contexts,source_cases:['kb_terms'],session:input.session||{},term_guard:'from_normalize'}}];
}


// 0.04) Hard deterministic NTFS timeline triad guard (MFT/USN/$LogFile)
const qTriad = String(query || '').toLowerCase();
if (false && (qTriad.includes('mft') || qTriad.includes('мфт')) && (qTriad.includes('usn') || qTriad.includes('journal') || qTriad.includes('$j')) && (qTriad.includes('$logfile') || qTriad.includes('logfile'))) {
  const ans = [
    'Коротко про різницю для таймлайну інциденту:',
    '• MFT — головний індекс файлів NTFS: дає метадані файлів/папок і базові часові мітки.',
    '• USN Journal ($J) — журнал змін: показує послідовність змін файлів (create/modify/rename/delete) у часі.',
