  const normalizedAliasText = rawQClean
    .replace(/^alias_import\s*/i, '')
    .split(/\n/)
    .map(l => l.replace(/#.*$/,'').trim())
    .filter(Boolean)
    .join('\n');
  const cmdRe = /alias\s+([^=]+?)\s*=\s*([^\n]+?)(?=(?:\s+alias\s+)|$)/gi;
  const parsed = [];
  let m;
  while ((m = cmdRe.exec(normalizedAliasText)) !== null) {
    const left = String(m[1] || '').trim().toLowerCase();
    const canonical = String(m[2] || '').trim().toLowerCase();
    if (!left || !canonical) continue;

    // left side may contain comma separated aliases
    const spokenList = left.split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
    for (const spoken of spokenList) {
      parsed.push({ spoken, canonical });
    }
  }

  if (!parsed.length) {
    const one = normalizedAliasText.match(/alias\s+([^=\n]+?)\s*=\s*([^\n]+)$/i);
    if (one) {
      const left = String(one[1]||'').trim().toLowerCase();
      const canonical = String(one[2]||'').trim().toLowerCase();
      if (left && canonical) {
        for (const spoken of left.split(',').map(s=>s.trim()).filter(Boolean)) parsed.push({ spoken, canonical });
      }
    }
  }

  if (!parsed.length) {
    return [{json:{chat_id:chatId,answer:'❌ Невірний формат.\nПриклад:\nalias павершел, повершел = powershell\n\nМожна кілька alias в одному повідомленні.',query,contexts,session:input.session||{}}}];
