    return [{json:{chat_id:chatId,answer:'⛔ Alias можуть змінювати лише адміністратори. Надішліть файл/список адміну на підтвердження.',query,contexts,session:input.session||{},alias_admin_required:true}}];
  }

  // normalize unique pairs in request
  const uniqMap = new Map();
  for (const p of parsed) {
    const k = `${p.spoken}=>${p.canonical}`;
    if (!uniqMap.has(k)) uniqMap.set(k, p);
  }
  const uniqPairs = [...uniqMap.values()];

  try {
    await this.helpers.httpRequest({ method:'GET', url:'http://qdrant:6333/collections/kb_terms', json:true });
  } catch(e) {
    try { await this.helpers.httpRequest({ method:'PUT', url:'http://qdrant:6333/collections/kb_terms', json:true, body:{ vectors:{ size:1024, distance:'Cosine' } } }); } catch(e2) {}
  }

  // load existing terms once and avoid duplicates
  const existing = new Set();
  try {
    let offset = null;
    for (let i=0;i<200;i++) {
      const body = { limit: 256, with_payload:true, with_vector:false };
      if (offset) body.offset = offset;
      const r = await this.helpers.httpRequest({ method:'POST', url:'http://qdrant:6333/collections/kb_terms/points/scroll', json:true, body });
      const pts = r?.result?.points || [];
      for (const p of pts) {
        const pl = p.payload || {};
        const t = String(pl.trigger||'').trim().toLowerCase();
        const c = String(pl.canonical||'').trim().toLowerCase();
        if (t && c) existing.add(`${t}=>${c}`);
      }
      offset = r?.result?.next_page_offset;
      if (!offset || !pts.length) break;
    }
  } catch(e) {}

  const toInsert = [];
  const skipped = [];
  for (const p of uniqPairs) {
    const key = `${p.spoken}=>${p.canonical}`;
    if (existing.has(key)) {
      skipped.push(p);
      continue;
    }
    const aid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&0x3|0x8)).toString(16)});
    toInsert.push({ id: aid, vector: Array(1024).fill(0.001), payload:{ trigger: p.spoken, canonical: p.canonical, intent:'alias_user', aliases:'', lang:'multi', ts:new Date().toISOString(), by_user: String(chatId||'') } });
  }

  if (toInsert.length) {
    await this.helpers.httpRequest({ method:'PUT', url:'http://qdrant:6333/collections/kb_terms/points', json:true, body:{ points: toInsert } });
  }

  let ans = `✅ Alias оброблено\nДодано: ${toInsert.length}\nПропущено (вже існує): ${skipped.length}`;
  const preview = uniqPairs.slice(0,12).map(a=>`• ${a.spoken} → ${a.canonical}`).join('\n');
