try {
  const qraw = String(query || '').toLowerCase();
  const months = {
    'січня':1,'января':1,
    'лютого':2,'февраля':2,
    'березня':3,'марта':3,
    'квітня':4,'апреля':4,
    'травня':5,'мая':5,
    'червня':6,'июня':6,
    'липня':7,'июля':7,
    'серпня':8,'августа':8,
    'вересня':9,'сентября':9,
    'жовтня':10,'октября':10,
    'листопада':11,'ноября':11,
    'грудня':12,'декабря':12,
  };

  const m = qraw.match(/\b(\d{1,2})\s+(січня|января|лютого|февраля|березня|марта|квітня|апреля|травня|мая|червня|июня|липня|июля|серпня|августа|вересня|сентября|жовтня|октября|листопада|ноября|грудня|декабря)\s+(\d{4})\b/i);
  const asksDate = /(що було|що сталось|що сталося|події|events|timeline)/i.test(qraw);

  if (m && asksDate && (session?.active_case_key || true)) {
    const dd = String(parseInt(m[1],10)).padStart(2,'0');
    const mm = String(months[m[2]] || '').padStart(2,'0');
    const yyyy = m[3];
    const d1 = `${dd}.${mm}.${yyyy}`;
    const d2 = `${yyyy}-${mm}-${dd}`;

    const filt = session?.active_case_key ? { must:[{ key:'case_key', match:{ value: session.active_case_key } }] } : undefined;
    const rr = await this.helpers.httpRequest({
      method:'POST',
      url: QDRANT + '/collections/kb_reports/points/scroll',
      body:{ limit:300, with_payload:true, with_vector:false, filter:filt },
      json:true,
      timeout:12000,
    });
    const pts = rr.result?.points || [];
    const hits=[];
    for (const p of pts) {
      const t = String(p.payload?.text || '');
      const idx = t.indexOf(d1) >= 0 ? t.indexOf(d1) : (t.indexOf(d2) >= 0 ? t.indexOf(d2) : -1);
      if (idx>=0) {
        hits.push({ src:p.payload?.source_file || 'kb_reports', snip:t.slice(Math.max(0,idx-120), idx+220).replace(/\s+/g,' ').trim() });
      }
    }

    // expand context window around matched chunks (±2)
    const bySrc = new Map();
    for (const p of pts) {
      const src = p.payload?.source_file || 'kb_reports';
      const ci = Number(p.payload?.chunk_index ?? -1);
      if (!bySrc.has(src)) bySrc.set(src, new Map());
      bySrc.get(src).set(ci, String(p.payload?.text || ''));
    }
    const expanded = [];
    for (const h of hits) {
      const srcMap = bySrc.get(h.src);
      if (!srcMap || Number.isNaN(h.ci) || h.ci < 0) { expanded.push({src:h.src,snip:h.snip}); continue; }
      let block='';
      for (let j=h.ci-2; j<=h.ci+2; j++) {
        if (srcMap.has(j)) block += ' ' + srcMap.get(j);
      }
      block = block.replace(/\s+/g,' ').trim();
      expanded.push({ src:h.src, snip:block.slice(0,1200) || h.snip });
    }

if (hits.length) {
      const ans = `Події за дату ${dd}.${mm}.${yyyy}:\n` + hits.slice(0,5).map((h,i)=>`${i+1}) ${h.snip}`).join('\n\n') + `\n\n📁 Джерела: ${[...new Set(expanded.map(h=>h.src))].slice(0,4).join(', ')}`;
      return [{ json:{ chat_id:chatId, answer:ans, query, contexts, source_cases:(sourceCases && sourceCases.length ? sourceCases : ['kb_reports']), session:input.session||{} } }];
    }
  }
} catch(e) {}



