// 0.52) Universal date/time query parser (UA/RU/EN + numeric formats)
try {
  const qRaw = String(query || '');
  const q = qRaw.toLowerCase();

  const asksTimeline = /(що було|що сталось|що сталося|поді[яї]|хронолог|timeline|what happened|events?|что было|событи)/i.test(q);

  const monthMap = {
    // UA
    'січ':1,'лют':2,'берез':3,'квіт':4,'трав':5,'черв':6,'лип':7,'серп':8,'верес':9,'жовт':10,'листоп':11,'груд':12,
    // RU
    'январ':1,'феврал':2,'март':3,'апрел':4,'май':5,'мая':5,'июн':6,'июл':7,'август':8,'сентябр':9,'октябр':10,'ноябр':11,'декабр':12,
    // EN
    'jan':1,'feb':2,'mar':3,'apr':4,'may':5,'jun':6,'jul':7,'aug':8,'sep':9,'oct':10,'nov':11,'dec':12
  };

  const pad2 = (n) => String(n).padStart(2,'0');
  const toYMD = (y,m,d) => `${y}-${pad2(m)}-${pad2(d)}`;
  const toDMY = (y,m,d) => `${pad2(d)}.${pad2(m)}.${y}`;

  let targetDates = []; // YYYY-MM-DD
  let monthScope = null; // {year?, month}

  // A) Numeric dates: DD.MM.YYYY / DD-MM-YYYY / DD/MM/YYYY
  let m = q.match(/\b(\d{1,2})[\.\-/ ](\d{1,2})[\.\-/ ](20\d{2})\b/);
  if (m) {
    const d = Number(m[1]), mo = Number(m[2]), y = Number(m[3]);
    if (d>=1 && d<=31 && mo>=1 && mo<=12) targetDates.push(toYMD(y,mo,d));
  }

  // B) ISO: YYYY-MM-DD / YYYY/MM/DD
  m = q.match(/\b(20\d{2})[\.\-/ ](\d{1,2})[\.\-/ ](\d{1,2})\b/);
  if (m) {
    const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);
    if (d>=1 && d<=31 && mo>=1 && mo<=12) targetDates.push(toYMD(y,mo,d));
  }

  // C) Word months: 2 травня 2025 / 2 мая 2025 / may 2 2025 / 2 may 2025
  m = q.match(/\b(\d{1,2})\s+([a-zа-яіїєґ]+)\s+(20\d{2})\b/i);
  if (m) {
    const d = Number(m[1]), monWord = m[2], y = Number(m[3]);
    const mk = Object.keys(monthMap).find(k => monWord.includes(k));
    if (mk) targetDates.push(toYMD(y, monthMap[mk], d));
  }
  m = q.match(/\b([a-zа-яіїєґ]+)\s+(\d{1,2}),?\s+(20\d{2})\b/i);
  if (m) {
    const monWord = m[1], d = Number(m[2]), y = Number(m[3]);
    const mk = Object.keys(monthMap).find(k => monWord.includes(k));
    if (mk) targetDates.push(toYMD(y, monthMap[mk], d));
  }

  // D) Month+year only: травень 2025 / may 2025
  m = q.match(/\b([a-zа-яіїєґ]+)\s+(20\d{2})\b/i);
  if (m) {
    const monWord = m[1], y = Number(m[2]);
    const mk = Object.keys(monthMap).find(k => monWord.includes(k));
    if (mk) monthScope = { year:y, month: monthMap[mk] };
  }

  // E) Month only: травень / май / may
  if (!monthScope) {
    const mm = Object.keys(monthMap).find(k => q.includes(k));
    if (mm) monthScope = { month: monthMap[mm] };
  }

  targetDates = [...new Set(targetDates)];

  if (asksTimeline && (targetDates.length || monthScope)) {
    const filter = session?.active_case_key ? { must:[{ key:'case_key', match:{ value: session.active_case_key } }] } : undefined;

    const rr = await this.helpers.httpRequest({
      method:'POST',
