      body:{ limit:400, with_payload:true, with_vector:false, filter },
      json:true,
      timeout:15000,
    });
    const pts = rr.result?.points || [];

    const hits = [];
    for (const p of pts) {
      const t = String(p.payload?.text || '');
      const src = p.payload?.source_file || 'kb_reports';

      const hasDate = (ymd) => {
        const [y,mo,d] = ymd.split('-');
        const dmy = `${d}.${mo}.${y}`;
        const dmy2 = `${Number(d)}.${Number(mo)}.${y}`;
        const iso = `${y}-${mo}-${d}`;
        return t.includes(dmy) || t.includes(dmy2) || t.includes(iso);
      };

      let matched = false;
      for (const ymd of targetDates) {
        if (hasDate(ymd)) { matched = true; break; }
      }

      if (!matched && monthScope) {
        const mo = pad2(monthScope.month);
        const y = monthScope.year ? String(monthScope.year) : null;
        const monthRegex = y
          ? new RegExp(`\\b(?:\\d{1,2}[\\.\\-/ ]${mo}[\\.\\-/ ]${y}|${y}[\\.\\-/ ]${mo}[\\.\\-/ ]\\d{1,2})\\b`)
          : new RegExp(`\\b(?:\\d{1,2}[\\.\\-/ ]${mo}[\\.\\-/ ]20\\d{2}|20\\d{2}[\\.\\-/ ]${mo}[\\.\\-/ ]\\d{1,2})\\b`);
        if (monthRegex.test(t)) matched = true;
      }

      if (matched) {
        const ci = Number(p.payload?.chunk_index ?? -1);
        hits.push({ src, ci, snip: t.slice(0, 420).replace(/\s+/g,' ').trim(), case_key:p.payload?.case_key || '' });
      }
    }


    // expand context window around matched chunks (±2)
    const bySrc = new Map();
    for (const p of pts) {
      const src = p.payload?.source_file || 'kb_reports';
      const ci = Number(p.payload?.chunk_index ?? -1);
      if (!bySrc.has(src)) bySrc.set(src, new Map());
      bySrc.get(src).set(ci, String(p.payload?.text || ''));
    }
    const expanded = [];
    for (const h of hits) {
      const srcMap = bySrc.get(h.src);
      if (!srcMap || Number.isNaN(h.ci) || h.ci < 0) { expanded.push({src:h.src,snip:h.snip}); continue; }
      let block='';
      for (let j=h.ci-2; j<=h.ci+2; j++) {
        if (srcMap.has(j)) block += ' ' + srcMap.get(j);
      }
      block = block.replace(/\s+/g,' ').trim();
      expanded.push({ src:h.src, snip:block.slice(0,1200) || h.snip });
    }

if (hits.length) {
      const title = targetDates.length
        ? `Події за дату ${targetDates[0]}:`
        : `Події за ${monthScope.month}${monthScope.year ? '.'+monthScope.year : ''}:`;
      // structured timeline formatter
      const summarize = (txt) => {
        const t = String(txt||'');
        const ips = [...new Set((t.match(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g) || []).slice(0,12))];
        const ssh = t.match(/ssh[\s\S]{0,140}?\d{2}[:.]\d{2}(?::\d{2})?/i);
        const brute = t.match(/brute[\s\S]{0,180}|підбор[\s\S]{0,180}/i);
        const art = t.match(/auth\.log|rdp|ngrok|service|task|runonce|run key|persistence/i);
        const lines=[];
        if (ssh) lines.push('• SSH/доступ: ' + ssh[0].replace(/\s+/g,' ').slice(0,220));
        if (brute) lines.push('• Brute-force/підбір: ' + brute[0].replace(/\s+/g,' ').slice(0,220));
        if (ips.length) lines.push('• IP: ' + ips.join(', '));
        if (art) lines.push('• Артефакти/контекст: ' + art[0]);
        if (!lines.length) lines.push('• ' + t.slice(0,260).replace(/\s+/g,' '));
        return lines.join('\n');
      };
      const ans = title + '\n' + expanded.slice(0,3).map((h,i)=>`${i+1}) ${summarize(h.snip)}`).join('\n\n') +
        `\n\n📁 Джерела: ${[...new Set(expanded.map(h=>h.src))].slice(0,6).join(', ')}`;
      return [{ json:{ chat_id:chatId, answer:ans, query, contexts, source_cases:(sourceCases && sourceCases.length ? sourceCases : ['kb_reports']), session:input.session||{} } }];
    }
  }
} catch(e) {}

