async function scrollPoints(collection, filter=null, maxRounds=120){
  let offset=null, rounds=0, out=[];
  while(rounds<maxRounds){
    const body={limit:256,with_payload:true,with_vector:false};
    if(filter) body.filter=filter;
    if(offset!==null) body.offset=offset;
    const rr=await this.helpers.httpRequest({method:'POST',url:QDRANT+`/collections/${collection}/points/scroll`,body,json:true,timeout:60000});
    const pts=rr?.result?.points||[]; out=out.concat(pts);
    offset=rr?.result?.next_page_offset; rounds++;
    if(!offset || pts.length===0) break;
  }
  return out;
}


