    if ((/який\s+ip|ip\s+джерел|джерело\s+ip/.test(ql)) && /smb/.test(ql)) {
      const m = caseText.match(/анонімн[\s\S]{0,200}?SMB[\s\S]{0,200}?(\b(?:\d{1,3}\.){3}\d{1,3}\b)/i) || caseText.match(/(\b(?:\d{1,3}\.){3}\d{1,3}\b)[\s\S]{0,200}?анонімн[\s\S]{0,200}?SMB/i) || caseText.match(/RD3\.exist\.ua[\s\S]{0,240}?(\b(?:\d{1,3}\.){3}\d{1,3}\b)/i);
      if (m) {
