    if (/macrium/.test(ql) && /(файл|назв|розмір|mrimg)/.test(ql)) {
      const found = [...caseText.matchAll(/(ESXI14[^\s,;:)]*?\.mrimg)\s*[—-]?\s*([0-9]+(?:\.[0-9]+)?\s*TB)/gi)].slice(0,4);
