      }
    }


    // Q4: period of suspicious episode on RD3.exist.ua
    if ((/період|вікно|дата|коли/.test(ql)) && /rd3\.exist\.ua|rd3/.test(ql)) {
      const m = caseText.match(/період\s*(\d{1,2}[–\-]\d{1,2}\.\d{2}\.\d{4})/i)
        || caseText.match(/(\d{1,2}\.\d{2}\.\d{4})\s*[–\-]\s*(\d{1,2}\.\d{2}\.\d{4})/i)
        || caseText.match(/за\s*(\d{4}[\-\.]\d{2}[\-\.]\d{2})[\s…\.\-]+(\d{4}[\-\.]\d{2}[\-\.]\d{2})/i);
      if (m) {
        let period = '';
        if (m[1] && m[2]) period = `${m[1]}–${m[2]}`;
        else period = m[1] || '';
        if (!period && m[0]) period = m[0];
        let ans = `Період підозрілого епізоду на RD3.exist.ua: ${period}.`;
        if (sourceCases.length) ans += '\n\n📁 Джерела: ' + sourceCases.slice(0,3).join(', ');
        if (searchMode) ans += '\n' + searchMode;
        return [{json:{chat_id:chatId,answer:ans,query,contexts,source_cases:(sourceCases && sourceCases.length ? sourceCases : ['model']),session}}];
      }
    }
  } catch(e) {}
