const followUpIntentAnywhere = /(детальніше|докладніше|розпиши|поясни|розкрий|уточни|більше\s+детал|продовж)/i;

const isQuote = quotePatterns.test(query);
const isFollowUp = followUpPatterns.test(query) || followUpIntentAnywhere.test(query) || query.length < 40;
const hasContext = session.last_contexts && session.last_contexts.length > 100;
const activeCase = session.active_case_key || null;
const lastQ = String(session.last_query || '').toLowerCase();
const caseCarry = !!(activeCase && /(кейс|інцидент|атака|що\s+було\s+в\s+цьому\s+кейс)/i.test(lastQ) && (isFollowUp || followUpIntentAnywhere.test(query)));

let mode = 'full_rag';

if (isQuote && hasContext) {
  mode = 'quote';
} else if ((isFollowUp && hasContext) || caseCarry) {
  mode = 'follow_up';
}

let enrichedQuery = query;
if ((mode === 'follow_up' || caseCarry) && session.last_query) {
  enrichedQuery = session.last_query + ' ' + query;
}

return [{
  json: {
    ...input,
    mode,
    enriched_query: enrichedQuery,
    use_last_contexts: mode === 'quote'
  }
}];

