// ═══ KAPE Parser v2: smart artifact detection by filename + content ═══
const input = $input.first().json;
const rawText = input.text || '';
const fileName = (input.file_name || input.full_path || '').toLowerCase();
const ext = (input.extension || fileName.split('.').pop()).toLowerCase();

// ─ Detect artifact type by filename pattern ─
const ARTIFACT_TYPES = {
  'prefetch':     { parser:'PECmd',     icon:'⚡', desc:'Prefetch/Program execution' },
  'peparser':     { parser:'PECmd',     icon:'⚡', desc:'PE file analysis' },
  'registry':     { parser:'RegExplorer',icon:'🗝️',  desc:'Registry hive data' },
  'ntuser':       { parser:'RegExplorer',icon:'🗝️',  desc:'User registry (NTUSER.DAT)' },
  'system':       { parser:'RegExplorer',icon:'🗝️',  desc:'SYSTEM registry' },
  'software':     { parser:'RegExplorer',icon:'🗝️',  desc:'SOFTWARE registry' },
  'sam':          { parser:'RegExplorer',icon:'👤',  desc:'SAM (user accounts)' },
  'security':     { parser:'RegExplorer',icon:'🛡️',  desc:'SECURITY registry/eventlog' },
  'evtx':         { parser:'EvtxECmd',  icon:'📋',  desc:'Windows Event Log' },
  'eventlog':     { parser:'EvtxECmd',  icon:'📋',  desc:'Windows Event Log' },
  'application':  { parser:'EvtxECmd',  icon:'📋',  desc:'Application Event Log' },
  'powershell':   { parser:'EvtxECmd',  icon:'🖥️',  desc:'PowerShell Event Log' },
  'mft':          { parser:'MFTECmd',   icon:'💾',  desc:'Master File Table' },
  'usnjrnl':      { parser:'MFTECmd',   icon:'💾',  desc:'USN Journal (file changes)' },
  'logfile':      { parser:'MFTECmd',   icon:'💾',  desc:'NTFS LogFile' },
  'shimcache':    { parser:'AppCompatCacheParser', icon:'🔄', desc:'ShimCache (app compat)' },
  'amcache':      { parser:'AmcacheParser', icon:'🔄', desc:'Amcache (program history)' },
  'lnk':          { parser:'LECmd',     icon:'🔗',  desc:'LNK shortcut files' },
  'jumplist':     { parser:'JLECmd',    icon:'📌',  desc:'Jump Lists' },
  'recycle':      { parser:'RBCmd',     icon:'🗑️',  desc:'Recycle Bin' },
  'srum':         { parser:'SrumECmd', icon:'📡', desc:'SRUM (network/process stats)' },
};

let artifactMeta = {parser:'Generic', icon:'📄', desc:'Generic log data'};
for(const [key, meta] of Object.entries(ARTIFACT_TYPES)){
  if(fileName.includes(key)){ artifactMeta=meta; break; }
}

// ─ Parse CSV ─
let artifacts = [];
let headers = [];

if(['csv','tsv'].includes(ext) && rawText.includes(',') || rawText.includes('\t')){
  try {
    const sep = ext==='tsv'||rawText.split('\t').length>rawText.split(',').length ? '\t' : ',';
    const lines = rawText.split('\n').map(l=>l.trim()).filter(l=>l);
    if(lines.length>1){
      // Parse headers - handle quoted CSV
      headers = lines[0].split(sep).map(h=>h.replace(/^"|"$/g,'').trim().toLowerCase());

      const getValue = (row, ...keys) => {
        for(const k of keys){
          const idx = headers.indexOf(k.toLowerCase());
          if(idx>=0 && row[idx]) return row[idx].replace(/^"|"$/g,'').trim();
        }
        return '';
      };

      for(let i=1; i<Math.min(lines.length,10001); i++){
        // Simple CSV split (handles most KAPE outputs)
        const vals = lines[i].split(sep).map(v=>v.replace(/^"|"$/g,'').trim());
        if(vals.length<2) continue;

        const row = {idx:i};
        headers.forEach((h,j)=>{ row[h]=vals[j]||''; });

        artifacts.push({
          type: artifactMeta.desc,
          parser: artifactMeta.parser,
          name:     getValue(vals,'name','filename','keyname','description','source','sourcename'),
          value:    getValue(vals,'value','data','path','fullpath','detail','sha256','execpath','executablepath'),
          timestamp:getValue(vals,'lastmodified','timestamp','datetime','created','modifiedtimestamp','lmd','lastrun'),
          hostname: getValue(vals,'hostname','computername','host','machinename','computer'),
          user:     getValue(vals,'username','user','sid','profilepath'),
          extra:    getValue(vals,'sha256','md5','sha1','hash','comment','category')
        });
      }
    }
  } catch(e){ artifacts=[]; }
}

// ─ Parse JSON ─
if(['json'].includes(ext) && artifacts.length===0){
  try {
    const parsed=JSON.parse(rawText);
    const arr=Array.isArray(parsed)?parsed:(parsed.entries||parsed.results||parsed.hits||[parsed]);
    for(const item of arr.slice(0,10000)){
      artifacts.push({
        type:artifactMeta.desc, parser:artifactMeta.parser,
        name:    item.Name||item.FileName||item.KeyName||item.ArtifactName||item.name||'',
        value:   item.Value||item.Data||item.Path||item.SHA256||item.Detail||item.value||'',
        timestamp:item.LastModified||item.Timestamp||item.DateTime||item.Created||item.timestamp||'',
        hostname:item.Hostname||item.ComputerName||item.Computer||item.hostname||'',
        user:    item.Username||item.User||item.SID||item.user||'',
        extra:   item.SHA256||item.MD5||item.Hash||item.Category||item.Comment||''
      });
    }
  } catch(e){}
}

// ─ Fallback: raw text ─
if(artifacts.length===0){
  artifacts=[{type:'raw_log',parser:'Generic',name:input.file_name||'',
    value:rawText.slice(0,2000),timestamp:'',hostname:'',user:'',extra:''}];
}

// ─ IOC extraction ─
const allText = artifacts.map(a=>`${a.name} ${a.value} ${a.extra} ${a.type}`).join(' ');
const privateIP=/^(10\.|172\.(1[6-9]|2\d|3[01])\.|192\.168\.|127\.|0\.)/;
const ips=[...new Set(allText.match(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g)||[])].filter(ip=>!privateIP.test(ip));
const md5s=[...new Set(allText.match(/\b[a-fA-F0-9]{32}\b/g)||[])];
const sha1s=[...new Set(allText.match(/\b[a-fA-F0-9]{40}\b/g)||[])];
const sha256s=[...new Set(allText.match(/\b[a-fA-F0-9]{64}\b/g)||[])];
const domains=[...new Set((allText.match(/\b(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+(?:com|net|org|ru|ua|io|gov|edu|biz|onion)\b/gi)||[]).filter(d=>d.length>6&&!d.endsWith('.exe')&&!d.endsWith('.dll')))];
const hosts=[...new Set(allText.match(/\b(?:WIN|DESKTOP|LAPTOP|SERVER|PC|WS|DC|SRV|WORKSTATION)-[A-Z0-9]{4,15}\b/gi)||[])];

const iocs=[
  ...ips.slice(0,100).map(v=>({type:'ip',value:v})),
  ...[...md5s,...sha1s,...sha256s].slice(0,50).map(v=>({type:'hash',value:v})),
  ...domains.slice(0,50).map(v=>({type:'domain',value:v})),
  ...hosts.slice(0,30).map(v=>({type:'hostname',value:v}))
];

// ─ Structured text for RAG ─
const structuredText = artifacts.slice(0,2000).map(a=>{
  let line=`[${artifactMeta.icon} ${a.parser}] ${a.name}`;
  if(a.value) line+=`: ${a.value.slice(0,200)}`;
  if(a.timestamp) line+=` | ${a.timestamp}`;
  if(a.hostname) line+=` | host:${a.hostname}`;
  if(a.user) line+=` | user:${a.user}`;
  if(a.extra) line+=` | ${a.extra.slice(0,80)}`;
  return line;
}).join('\n');

return [{json:{
  ...input,
  text: structuredText || rawText,
  artifact_type: artifactMeta.desc,
  artifact_parser: artifactMeta.parser,
  artifacts_count: artifacts.length,
  iocs, iocs_count: iocs.length,
  ioc_summary: {
    ips: ips.length, hashes: md5s.length+sha1s.length+sha256s.length,
    domains: domains.length, hosts: hosts.length
  }
}}];

