// ═══ Extract CSV/JSON from ZIP with progress reporting ═══
const binary = $input.first().binary?.data;
const CFG = $('⚙️ Config').first().json.CONFIG;
const meta   = $input.first().json;
const BOT = CFG.BOT;

if(!binary?.data) throw new Error('Немає бінарних даних');

const buf = Buffer.from(binary.data,'base64');
const results = [];
let offset = 0;

const readUint16 = (b,o)=>b[o]|(b[o+1]<<8);
const readUint32 = (b,o)=>b[o]|(b[o+1]<<8)|(b[o+2]<<16)|(b[o+3]<<24);

while(offset<buf.length-30){
  const sig=readUint32(buf,offset);
  if(sig!==0x04034b50){offset++;continue;}
  const comprMethod=readUint16(buf,offset+8);
  const compSize   =readUint32(buf,offset+18);
  const uncompSize =readUint32(buf,offset+22);
  const fnLen      =readUint16(buf,offset+26);
  const extraLen   =readUint16(buf,offset+28);
  const fileName   =buf.slice(offset+30,offset+30+fnLen).toString('utf-8');
  const dataStart  =offset+30+fnLen+extraLen;
  const ext=fileName.split('.').pop().toLowerCase();
  const isDir=fileName.endsWith('/')||fileName.endsWith('\\');

  if(!isDir&&['csv','json','txt','log','tsv'].includes(ext)){
    try {
      let content='';
      if(comprMethod===0){
        content=buf.slice(dataStart,dataStart+uncompSize).toString('utf-8');
      } else if(comprMethod===8){
        const zlib=require('zlib');
        content=zlib.inflateRawSync(buf.slice(dataStart,dataStart+compSize)).toString('utf-8');
      }
      if(content.length>10){
        const shortName=fileName.split('/').pop().split('\\').pop();
        results.push({fileName:shortName,fullPath:fileName,ext,content,size:content.length});
      }
    } catch(e){}
  }
  offset=dataStart+(compSize||uncompSize||1);
  if(offset<=dataStart) break; // safety
}

if(results.length===0) throw new Error('ZIP не містить CSV/JSON файлів або стиснуто несумісним методом');

// Sort: larger files first (more data)
results.sort((a,b)=>b.size-a.size);

await this.helpers.httpRequest({method:'POST',url:BOT+'/sendMessage',
  body:{chat_id:meta.chat_id,
    text:`📦 ZIP розпаковано!\n📄 Знайдено файлів: ${results.length}\n📊 Обробляю по черзі...`},
  json:true
});

return results.map((r,i)=>({json:{
  ...meta,
  file_name:r.fileName, full_path:r.fullPath,
  extension:r.ext, text:r.content,
  text_length:r.content.length, needs_ocr:false,
  from_zip:true, file_index:i, total_files:results.length
}}));

// ═══ KAPE Parser v2: smart artifact detection by filename + content ═══
const input = $input.first().json;
const rawText = input.text || '';
const fileName = (input.file_name || input.full_path || '').toLowerCase();
const ext = (input.extension || fileName.split('.').pop()).toLowerCase();

// ─ Detect artifact type by filename pattern ─
const ARTIFACT_TYPES = {
  'prefetch':     { parser:'PECmd',     icon:'⚡', desc:'Prefetch/Program execution' },
  'peparser':     { parser:'PECmd',     icon:'⚡', desc:'PE file analysis' },
  'registry':     { parser:'RegExplorer',icon:'🗝️',  desc:'Registry hive data' },
  'ntuser':       { parser:'RegExplorer',icon:'🗝️',  desc:'User registry (NTUSER.DAT)' },
  'system':       { parser:'RegExplorer',icon:'🗝️',  desc:'SYSTEM registry' },
  'software':     { parser:'RegExplorer',icon:'🗝️',  desc:'SOFTWARE registry' },
  'sam':          { parser:'RegExplorer',icon:'👤',  desc:'SAM (user accounts)' },
  'security':     { parser:'RegExplorer',icon:'🛡️',  desc:'SECURITY registry/eventlog' },
  'evtx':         { parser:'EvtxECmd',  icon:'📋',  desc:'Windows Event Log' },
  'eventlog':     { parser:'EvtxECmd',  icon:'📋',  desc:'Windows Event Log' },
  'application':  { parser:'EvtxECmd',  icon:'📋',  desc:'Application Event Log' },
  'powershell':   { parser:'EvtxECmd',  icon:'🖥️',  desc:'PowerShell Event Log' },
  'mft':          { parser:'MFTECmd',   icon:'💾',  desc:'Master File Table' },
  'usnjrnl':      { parser:'MFTECmd',   icon:'💾',  desc:'USN Journal (file changes)' },
  'logfile':      { parser:'MFTECmd',   icon:'💾',  desc:'NTFS LogFile' },
  'shimcache':    { parser:'AppCompatCacheParser', icon:'🔄', desc:'ShimCache (app compat)' },
  'amcache':      { parser:'AmcacheParser', icon:'🔄', desc:'Amcache (program history)' },
  'lnk':          { parser:'LECmd',     icon:'🔗',  desc:'LNK shortcut files' },
  'jumplist':     { parser:'JLECmd',    icon:'📌',  desc:'Jump Lists' },
  'recycle':      { parser:'RBCmd',     icon:'🗑️',  desc:'Recycle Bin' },
  'srum':         { parser:'SrumECmd', icon:'📡', desc:'SRUM (network/process stats)' },
};

let artifactMeta = {parser:'Generic', icon:'📄', desc:'Generic log data'};
for(const [key, meta] of Object.entries(ARTIFACT_TYPES)){
  if(fileName.includes(key)){ artifactMeta=meta; break; }
}

// ─ Parse CSV ─
let artifacts = [];
let headers = [];

if(['csv','tsv'].includes(ext) && rawText.includes(',') || rawText.includes('\t')){
  try {
    const sep = ext==='tsv'||rawText.split('\t').length>rawText.split(',').length ? '\t' : ',';
    const lines = rawText.split('\n').map(l=>l.trim()).filter(l=>l);
    if(lines.length>1){
      // Parse headers - handle quoted CSV
      headers = lines[0].split(sep).map(h=>h.replace(/^"|"$/g,'').trim().toLowerCase());

      const getValue = (row, ...keys) => {
        for(const k of keys){
          const idx = headers.indexOf(k.toLowerCase());
          if(idx>=0 && row[idx]) return row[idx].replace(/^"|"$/g,'').trim();
        }
        return '';
      };

      for(let i=1; i<Math.min(lines.length,10001); i++){
        // Simple CSV split (handles most KAPE outputs)
        const vals = lines[i].split(sep).map(v=>v.replace(/^"|"$/g,'').trim());
        if(vals.length<2) continue;

        const row = {idx:i};
        headers.forEach((h,j)=>{ row[h]=vals[j]||''; });

        artifacts.push({
          type: artifactMeta.desc,
          parser: artifactMeta.parser,
          name:     getValue(vals,'name','filename','keyname','description','source','sourcename'),
          value:    getValue(vals,'value','data','path','fullpath','detail','sha256','execpath','executablepath'),
          timestamp:getValue(vals,'lastmodified','timestamp','datetime','created','modifiedtimestamp','lmd','lastrun'),
          hostname: getValue(vals,'hostname','computername','host','machinename','computer'),
          user:     getValue(vals,'username','user','sid','profilepath'),
          extra:    getValue(vals,'sha256','md5','sha1','hash','comment','category')
        });
      }
    }
  } catch(e){ artifacts=[]; }
}

// ─ Parse JSON ─
if(['json'].includes(ext) && artifacts.length===0){
  try {
    const parsed=JSON.parse(rawText);
    const arr=Array.isArray(parsed)?parsed:(parsed.entries||parsed.results||parsed.hits||[parsed]);
    for(const item of arr.slice(0,10000)){
      artifacts.push({
        type:artifactMeta.desc, parser:artifactMeta.parser,
        name:    item.Name||item.FileName||item.KeyName||item.ArtifactName||item.name||'',
        value:   item.Value||item.Data||item.Path||item.SHA256||item.Detail||item.value||'',
        timestamp:item.LastModified||item.Timestamp||item.DateTime||item.Created||item.timestamp||'',
        hostname:item.Hostname||item.ComputerName||item.Computer||item.hostname||'',
        user:    item.Username||item.User||item.SID||item.user||'',
        extra:   item.SHA256||item.MD5||item.Hash||item.Category||item.Comment||''
      });
    }
  } catch(e){}
}

// ─ Fallback: raw text ─
if(artifacts.length===0){
  artifacts=[{type:'raw_log',parser:'Generic',name:input.file_name||'',
    value:rawText.slice(0,2000),timestamp:'',hostname:'',user:'',extra:''}];
}

// ─ IOC extraction ─
const allText = artifacts.map(a=>`${a.name} ${a.value} ${a.extra} ${a.type}`).join(' ');
const privateIP=/^(10\.|172\.(1[6-9]|2\d|3[01])\.|192\.168\.|127\.|0\.)/;
const ips=[...new Set(allText.match(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g)||[])].filter(ip=>!privateIP.test(ip));
const md5s=[...new Set(allText.match(/\b[a-fA-F0-9]{32}\b/g)||[])];
const sha1s=[...new Set(allText.match(/\b[a-fA-F0-9]{40}\b/g)||[])];
const sha256s=[...new Set(allText.match(/\b[a-fA-F0-9]{64}\b/g)||[])];
const domains=[...new Set((allText.match(/\b(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+(?:com|net|org|ru|ua|io|gov|edu|biz|onion)\b/gi)||[]).filter(d=>d.length>6&&!d.endsWith('.exe')&&!d.endsWith('.dll')))];
const hosts=[...new Set(allText.match(/\b(?:WIN|DESKTOP|LAPTOP|SERVER|PC|WS|DC|SRV|WORKSTATION)-[A-Z0-9]{4,15}\b/gi)||[])];

const iocs=[
  ...ips.slice(0,100).map(v=>({type:'ip',value:v})),
  ...[...md5s,...sha1s,...sha256s].slice(0,50).map(v=>({type:'hash',value:v})),
  ...domains.slice(0,50).map(v=>({type:'domain',value:v})),
  ...hosts.slice(0,30).map(v=>({type:'hostname',value:v}))
];

// ─ Structured text for RAG ─
const structuredText = artifacts.slice(0,2000).map(a=>{
  let line=`[${artifactMeta.icon} ${a.parser}] ${a.name}`;
  if(a.value) line+=`: ${a.value.slice(0,200)}`;
  if(a.timestamp) line+=` | ${a.timestamp}`;
  if(a.hostname) line+=` | host:${a.hostname}`;
  if(a.user) line+=` | user:${a.user}`;
  if(a.extra) line+=` | ${a.extra.slice(0,80)}`;
  return line;
}).join('\n');

return [{json:{
  ...input,
  text: structuredText || rawText,
  artifact_type: artifactMeta.desc,
  artifact_parser: artifactMeta.parser,
  artifacts_count: artifacts.length,
  iocs, iocs_count: iocs.length,
  ioc_summary: {
    ips: ips.length, hashes: md5s.length+sha1s.length+sha256s.length,
    domains: domains.length, hosts: hosts.length
  }
}}];

let CFG; try { CFG = $('⚙️ Config').first().json.CONFIG; } catch(e) { throw new Error('CONFIG_MISSING: ⚙️ Config node required'); }

// Save KAPE chunk: embed + store + tag IOCs with source=kape
const input = $input.first().json;
const QDRANT = CFG.QDRANT;
const OLLAMA = CFG.OLLAMA;
const EMBED  = 'bge-m3';

const text = String(input.text||'');
if(text.length<10) return [{json:{skipped:true,file:input.file_name}}];

const uuidv4=()=>'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{
  const r=Math.random()*16|0;return(c==='x'?r:(r&0x3|0x8)).toString(16);
});
const embed=async(prompt)=>{
  const r=await this.helpers.httpRequest({
    method:'POST',url:OLLAMA+'/v1/embeddings',
    body:{model:EMBED,input:prompt.slice(0,2000)},json:true,timeout:60000
  });
  const vec = (r.data && r.data[0] && r.data[0].embedding) ? r.data[0].embedding : r.embedding;
  if(!Array.isArray(vec)) throw new Error('No embedding');
  return vec;
};

const CHUNK=500; const OVERLAP=80;
const lines=text.split('\n').filter(l=>l.trim().length>10);
const chunks=[];
let cur='';
for(const line of lines){
  if(chunks.length>=300) break;
  if((cur+'\n'+line).length>CHUNK&&cur.length>30){
    chunks.push(cur.trim());
    cur=cur.slice(-OVERLAP)+'\n'+line;
  } else { cur+='\n'+line; }
}
if(cur.trim().length>20&&chunks.length<300) chunks.push(cur.trim());

let saved=0;
const errors=[];
const BATCH=5;
for(let b=0;b<chunks.length;b+=BATCH){
  const batch=chunks.slice(b,b+BATCH);
  const points=[];
  for(const [i,chunk] of batch.entries()){
    try {
      const vec=await embed(chunk);
      points.push({id:uuidv4(),vector:vec,payload:{
        text:chunk, chunk_index:b+i, source_file:input.file_name,
        full_path:input.full_path||'', case_key:input.case_key,
        doc_type:'kape', artifact_type:input.artifact_type||'',
        artifact_parser:input.artifact_parser||'',
        uploaded_by:input.user_id, uploaded_at:new Date().toISOString()
      }});
    } catch(e){ errors.push('E:'+e.message.slice(0,50)); }
  }
  if(points.length>0){
    try {
      await this.helpers.httpRequest({
        method:'PUT',url:QDRANT+'/collections/kb_logs/points',
        body:{points},json:true,timeout:60000
      });
      saved+=points.length;
    } catch(e){ errors.push('S:'+e.message.slice(0,50)); }
  }
}

// Save IOCs tagged as source=kape for cross-reference
const iocs=Array.isArray(input.iocs)?input.iocs:[];
let savedIOCs=0;
for(const ioc of iocs.slice(0,50)){
  try {
    const vec=await embed(ioc.type+': '+ioc.value);
    await this.helpers.httpRequest({
      method:'PUT',url:QDRANT+'/collections/kb_iocs/points',
      body:{points:[{id:uuidv4(),vector:vec,payload:{
        ioc_type:ioc.type, value:ioc.value,
        case_key:input.case_key, source:'kape',
        source_file:input.file_name, first_seen:new Date().toISOString()
      }}]}, json:true,timeout:30000
    });
    savedIOCs++;
  } catch(e){}
}

return [{json:{
  chat_id:input.chat_id, file_name:input.file_name,
  case_key:input.case_key, doc_type:'kape',
  chunks_saved:saved, iocs_saved:savedIOCs,
  file_index:input.file_index||0, total_files:input.total_files||1
}}];

const all=($input.all()||[]);
const first=all[0]?.json||{};
const chatId=first.chat_id;
const totalChunks=all.reduce((s,i)=>s+(i.json.chunks_saved||0),0);
const totalIOCs  =all.reduce((s,i)=>s+(i.json.iocs_saved||0),0);
const fileCount  =all.filter(i=>!i.json.skipped).length;

// Pass aggregated stats to auto-analyzer
return [{json:{
  chat_id:chatId, case_key:first.case_key,
  doc_type:'kape', collection:'kb_logs',
  total_chunks:totalChunks, total_files:fileCount,
  total_iocs:totalIOCs
}}];

let CFG; try { CFG = $('⚙️ Config').first().json.CONFIG; } catch(e) { throw new Error('CONFIG_MISSING: ⚙️ Config node required'); }

