// ROUTING LOGIC (fixed 2026-05-01):
// 1. pending_manual_ioc → mode:manual_ioc (is_case_name:true)
// 2. kape_waiting_for='kape_case_name' → mode:kape_case_name
// 3. case_waiting_for='create_case_name' → mode:create_case_name
// 4. flow_state='pending_manual_ioc' → mode:manual_ioc
// 5. active_case_key set → is_case_name:FALSE, pass to normal text flow (FIXED: was routing to dfir_chat_queued which broke Process Case Name)
// 6. default → is_case_name:false
// NOTE: After power outage stale state can cause wrong routing. Clear kb_sessions + kb_user_state for the user.
// Intercept text messages: route typed case names and manual IOC mode; otherwise pass through
const tg = $('Telegram Trigger').first().json || {};
const text = String(tg.message?.text || '').trim();
const chatId = tg.message?.chat?.id;
const userId = tg.message?.from?.id;
const userIdStr = String(userId || '');
const QDRANT = 'http://qdrant:6333';

if (!text) return [{json:{is_case_name:false,text,chat_id:chatId,user_id:userId}}];
if (text.startsWith('/')) return [{json:{is_case_name:false,text,chat_id:chatId,user_id:userId}}];

let state = null;
let stateByNum = null;
let stateByStr = null;
try {
  if (userId !== undefined && userId !== null) {
    const sr = await this.helpers.httpRequest({
      method:'POST', url:QDRANT+'/collections/kb_user_state/points/scroll', json:true,
      body:{limit:5,with_payload:true,with_vector:false,filter:{must:[{key:'user_id',match:{value:userId}}]}}
    });
    const pts = sr?.result?.points || [];
    stateByNum = (pts.find(p => p?.payload?.admin_waiting_for === 'user_label') || pts[0] || {}).payload || null;
  }
  if (userIdStr) {
    const sr2 = await this.helpers.httpRequest({
      method:'POST', url:QDRANT+'/collections/kb_user_state/points/scroll', json:true,
      body:{limit:5,with_payload:true,with_vector:false,filter:{must:[{key:'user_id',match:{value:userIdStr}}]}}
    });
    const pts2 = sr2?.result?.points || [];
    stateByStr = (pts2.find(p => p?.payload?.admin_waiting_for === 'user_label') || pts2[0] || {}).payload || null;
  }
  // Admin next-message states must beat stale manual-IOC states. Qdrant may contain both numeric and string user_id records.
  state = [stateByNum, stateByStr].find(s => s?.admin_waiting_for === 'user_label') || stateByNum || stateByStr || null;
} catch(e) {}


// Admin label capture: after 🏷 button, the next admin text becomes private note for selected Telegram ID.
if (state?.admin_waiting_for === 'user_label' && String(userIdStr)==='CHANGE_ME_OWNER_CHAT_ID') {
  const target=String(state.target_user||'').trim();
  const note = text === '-' ? '' : text.slice(0,300);
  let ok=false, err='';
  if (target) {
    try {
      const r=await this.helpers.httpRequest({method:'POST',url:'http://case-maintainer:8787/admin-user-label',json:true,timeout:10000,body:{user_id:target,note}});
      ok=!!r.ok;
      if(!ok) err=String(r.error||'');
    } catch(e) { err=String(e.message||e); }
  } else { err='target missing'; }
  try { await this.helpers.httpRequest({method:'POST',url:QDRANT+'/collections/kb_user_state/points/delete',json:true,body:{filter:{should:[{key:'user_id',match:{value:userId}},{key:'user_id',match:{value:userIdStr}}]}}}); } catch(e){}
  const msg = ok ? `✅ Підпис збережено для ${target}: ${note || '—'}` : `⚠️ Не вдалося зберегти підпис для ${target}: ${String(err).slice(0,160)}`;
  // send via Config BOT if available from workflow
  try {
    let CFG; try { CFG = $('⚙️ Config').first().json.CONFIG; } catch(e) { CFG = {}; }
    if (CFG.BOT) await this.helpers.httpRequest({method:'POST',url:CFG.BOT+'/sendMessage',json:true,body:{chat_id:chatId,text:msg,reply_markup:{inline_keyboard:[[{text:'👤 Відкрити користувача',callback_data:'adm_u_'+target}],[{text:'🛠 Адмін-меню',callback_data:'admin_monitor'}]]}}});
  } catch(e) {}
  return [{json:{is_case_name:true, mode:'dfir_chat_handled', admin_label_saved:ok, chat_id:chatId, user_id:userId}}];
}

// PRIORITY: active_case_key check FIRST (before kape_waiting_for to prevent routing questions as case names)
let sess = {};
let sessErr = '';
let sessRaw = null;
try {
  const ss = await this.helpers.httpRequest({
    method:'POST', url:QDRANT+'/collections/kb_sessions/points/scroll', json:true,
    body:{limit:1,with_payload:true,with_vector:false,filter:{must:[{key:'chat_id',match:{value:chatId}}]}}
  });
  sessRaw = ss;
  sess = ss?.result?.points?.[0]?.payload || {};
} catch(e) { sessErr = String(e); }

// Explicit waiting states from buttons have priority over stale chat/session modes.
// This prevents an old pending_manual_ioc flag from hijacking new case creation.
if (state?.case_waiting_for === 'create_case_name') {
  return [{json:{is_case_name:true, mode:'create_case_name', raw_text:text, chat_id:chatId, user_id:userId, state}}];
}
if (state?.kape_waiting_for === 'kape_case_name') {
  return [{json:{is_case_name:true, mode:'kape_case_name', raw_text:text, chat_id:chatId, user_id:userId, state}}];
}

if (sess?.flow_state === 'pending_manual_ioc') {
  return [{json:{is_case_name:true, mode:'manual_ioc', raw_text:text, chat_id:chatId, user_id:userId, state:state||{}, session:sess}}];
}

if (state?.pending_manual_ioc === true) {
  return [{json:{is_case_name:true, mode:'manual_ioc', raw_text:text, chat_id:chatId, user_id:userId, state}}];
}

if (sess?.active_case_key && text.length > 3) {
  // Active case question → dfir-chat ReAct agent (fire-and-forget, sends answer to Telegram)
  let dfirErr = '';
  try {
    await this.helpers.httpRequest({
      method:'POST', url:'http://case-maintainer:8787/dfir-chat', json:true, timeout:8000,
      body:{ case_key: sess.active_case_key, question: text, chat_id: String(chatId) }
    });
  } catch(e) { dfirErr = String(e); }
  return [{json:{is_case_name:true, mode:'dfir_chat_handled', chat_id:chatId, user_id:userId, _dfirErr:dfirErr}}];
}

// DEBUG: return early with diagnostic info if sess not found
if (text.length > 3 && !sess?.active_case_key && !state?.kape_waiting_for && !state?.case_waiting_for && state?.pending_manual_ioc !== true && sess?.flow_state !== 'pending_manual_ioc') {
  return [{json:{is_case_name:false, text, chat_id:chatId, user_id:userId, _debug:{chatId, chatIdType:typeof chatId, sessFound:Object.keys(sess).length>0, sessErr, sessRaw_points: sessRaw?.result?.points?.length ?? -1, stateKW:state?.kape_waiting_for}}}];
}

return [{json:{is_case_name:false, text, chat_id:chatId, user_id:userId}}];

// Process the typed case name and kick off download
const input=$input.first().json;
const CFG = $('⚙️ Config').first().json.CONFIG;
const text=(input.raw_text||'').trim();
const state=input.state||{};
const chatId=input.chat_id;
const userId=input.user_id;
const BOT = CFG.BOT;
const QDRANT = CFG.QDRANT;


const mode = input.mode || (state?.case_waiting_for==='create_case_name' ? 'create_case_name' : 'kape_case_name');

// Every branch that has finished its job returns [] (no item). A non-empty item here flows on
// into Get File Path, whose Qdrant fallback picks up ANY stale pending_file_id - that is how a
// typed case name re-downloaded a 2-day-old PDF and ran it through OCR as case "file" (2026-09-02).
// dfir-chat handled upstream — stop this branch (dfir-chat already sent answer to Telegram)
if (mode === 'dfir_chat_handled') return [];

function translitCyr(s){
  const M={'а':'a','б':'b','в':'v','г':'h','ґ':'g','д':'d','е':'e','є':'ie','ж':'zh','з':'z','и':'y','і':'i','ї':'i','й':'i','к':'k','л':'l','м':'m','н':'n','о':'o','п':'p','р':'r','с':'s','т':'t','у':'u','ф':'f','х':'kh','ц':'ts','ч':'ch','ш':'sh','щ':'shch','ь':'','ю':'iu','я':'ia','ё':'e','ы':'y','э':'e','ъ':''};
  return String(s||'').split('').map(function(ch){var low=ch.toLowerCase();if(M.hasOwnProperty(low)){var r=M[low];return ch===low?r:(r?r[0].toUpperCase()+r.slice(1):r);}return ch;}).join('');
}
function normalizeCaseName(s){
  let t=String(s||'').trim().replace(/\s+/g,' ');
  let datePart=null;
  // '_' belongs in this list: the recommended format is a date then the name, and people
  // type it joined by underscores (02_09_2026_DVB_...). Without '_' the date was not seen
  // and today's date got prepended on top of it.
  const m=t.match(/^(\d{1,2})[._\-\/ ](\d{1,2})[._\-\/ ](\d{4})(.*)$/);
  if (m){
    datePart=m[1].padStart(2,'0')+'_'+m[2].padStart(2,'0')+'_'+m[3];
    t=(m[4]||'').trim();
  }
  if(!datePart){
    // ISO first: 2026-09-02_name / 2026_09_02 name
    const iso=t.match(/^(\d{4})[._\-\/ ](\d{1,2})[._\-\/ ](\d{1,2})(.*)$/);
    if (iso){
      datePart=iso[3].padStart(2,'0')+'_'+iso[2].padStart(2,'0')+'_'+iso[1];
      t=(iso[4]||'').trim();
    }
  }
  if(!datePart){
    const dt=new Date();
    datePart=String(dt.getDate()).padStart(2,'0')+'_'+String(dt.getMonth()+1).padStart(2,'0')+'_'+dt.getFullYear();
  }
  t=translitCyr(t);
  t=t.replace(/[^a-zA-Z0-9\s_]/g,' ').replace(/\s+/g,' ').trim();
  let name=t.slice(0,60).replace(/\s+/g,'_').replace(/_{2,}/g,'_').replace(/^_+|_+$/g,'');
  return name ? (datePart+'_'+name) : datePart;
}

const caseName=normalizeCaseName(text);


if (mode === 'manual_ioc') {
  const raw = String(text||'').trim();
  const typeMap = { hash:'hash_sha256', sha256:'hash_sha256', sha1:'hash_sha1', md5:'hash_md5', ip:'ip', domain:'domain', url:'url', file:'file_name', filename:'file_name' };
  const normType = (t) => typeMap[String(t||'').toLowerCase().trim()] || String(t||'').toLowerCase().trim();
  const items = [];
  const add = (t,v) => { const tv=String(v||'').trim(); const tt=normType(t); if (tt && tv) items.push({ioc_type:tt, value:tv}); };

  // 1) strict typed format (supports single/multi-line)
  for (const line of raw.split(/\n+/)) {
    const m = line.match(/^\s*([a-zA-Zа-яА-ЯіІїЇєЄ0-9_\-]+)\s*:\s*(.+)\s*$/);
    if (m) add(m[1], m[2]);
  }

  // 2) free-form extraction
  const rxIp = /\b(?:\d{1,3}\.){3}\d{1,3}\b/g;
  const rxUrl = /https?:\/\/[^\s"'<>]+/gi;
  const rxSha256 = /\b[a-fA-F0-9]{64}\b/g;
  const rxSha1 = /\b[a-fA-F0-9]{40}\b/g;
  const rxMd5 = /\b[a-fA-F0-9]{32}\b/g;
  const rxDomain = /\b(?:[a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}\b/g;
  for (const v of (raw.match(rxUrl) || [])) add('url', v);
  for (const v of (raw.match(rxIp) || [])) add('ip', v);
  for (const v of (raw.match(rxSha256) || [])) add('hash_sha256', v);
  for (const v of (raw.match(rxSha1) || [])) add('hash_sha1', v);
  for (const v of (raw.match(rxMd5) || [])) add('hash_md5', v);
  for (const v of (raw.match(rxDomain) || [])) {
    const d = String(v).toLowerCase();
    if (!/^\d+\.\d+\.\d+\.\d+$/.test(d) && !d.startsWith('http')) add('domain', d);
  }

  // dedup
  const uniq=[]; const seen=new Set();
  for (const it of items) {
    const k=`${it.ioc_type}:${String(it.value).toLowerCase()}`;
    if (seen.has(k)) continue;
    seen.add(k); uniq.push(it);
  }

  if (!uniq.length) {
    await this.helpers.httpRequest({method:'POST',url:BOT+'/sendMessage',json:true,body:{chat_id:chatId,text:'❌ Не знайшов IOC у повідомленні. Надішліть `тип:значення` або список IOC (ip/url/domain/hash).',parse_mode:'Markdown'}});
    return [];
  }

  // active case from session
  let activeCase = (input.session||{}).active_case_key || null;
  if (!activeCase) {
    try {
      const sr = await this.helpers.httpRequest({method:'POST',url:QDRANT+'/collections/kb_sessions/points/scroll',json:true,body:{limit:1,with_payload:true,with_vector:false,filter:{must:[{key:'chat_id',match:{value:chatId}}]}}});
      activeCase = sr?.result?.points?.[0]?.payload?.active_case_key || null;
    } catch(e) {}
  }
  if (!activeCase) {
    await this.helpers.httpRequest({method:'POST',url:BOT+'/sendMessage',json:true,body:{chat_id:chatId,text:'❌ Немає активного кейсу. Спочатку оберіть кейс.'}});
    return [];
  }

  const points = uniq.slice(0,120).map(it => ({
    id:'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&0x3|0x8)).toString(16)}),
    vector:Array(1024).fill(0.001),
    payload:{case_key:activeCase,ioc_type:it.ioc_type,value:it.value,source:'manual',source_file:'manual_input',doc_type:'manual',uploaded_by:String(userId||''),uploaded_at:new Date().toISOString()}
  }));
  await this.helpers.httpRequest({method:'PUT',url:QDRANT+'/collections/kb_iocs/points',json:true,body:{points}});

  const t='batch';
  const v=`${points.length}`;
  // clear pending_manual_ioc flag in kb_user_state
  try {
    const uid2=String(userId||'');
    if (uid2) {
      const su=await this.helpers.httpRequest({method:'POST',url:'http://qdrant:6333/collections/kb_user_state/points/scroll',json:true,body:{limit:1,with_payload:true,with_vector:false,filter:{must:[{key:'user_id',match:{value:uid2}}]}}});
      const prevu=su?.result?.points?.[0]?.payload||{};
      const idu2='xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&0x3|0x8)).toString(16)});
      await this.helpers.httpRequest({method:'POST',url:'http://qdrant:6333/collections/kb_user_state/points/delete',json:true,body:{filter:{must:[{key:'user_id',match:{value:uid2}}]}}});
      await this.helpers.httpRequest({method:'PUT',url:'http://qdrant:6333/collections/kb_user_state/points',json:true,body:{points:[{id:idu2,vector:Array(1024).fill(0.001),payload:{...prevu,user_id:uid2,pending_manual_ioc:false,last_manual_ioc_result:`${t}:${v}`,updated_at:new Date().toISOString()}}]}});
    }
  } catch(e) {}

  // clear pending flow_state
  try {
    const sr = await this.helpers.httpRequest({method:'POST',url:QDRANT+'/collections/kb_sessions/points/scroll',json:true,body:{limit:1,with_payload:true,with_vector:false,filter:{must:[{key:'chat_id',match:{value:chatId}}]}}});
    let session = sr?.result?.points?.[0]?.payload || {};
    session.flow_state = null;
    session.chat_id = chatId;
    session.updated_at = new Date().toISOString();
    const id2='xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&0x3|0x8)).toString(16)});
    await this.helpers.httpRequest({method:'POST',url:QDRANT+'/collections/kb_sessions/points/delete',json:true,body:{filter:{must:[{key:'chat_id',match:{value:chatId}}]}}});
    await this.helpers.httpRequest({method:'PUT',url:QDRANT+'/collections/kb_sessions/points',json:true,body:{points:[{id:id2,vector:Array(1024).fill(0.001),payload:session}]}});
  } catch(e) {}

  await this.helpers.httpRequest({method:'POST',url:BOT+'/sendMessage',json:true,body:{chat_id:chatId,text:`✅ Додано IOC: ${points.length}\nКейс: ${String(activeCase).replace(/_/g,' ')}`}});
  return [];
}


if (mode === 'create_case_name') {
  // clear waiting state
  try {
    await this.helpers.httpRequest({ method:'POST',url:QDRANT+'/collections/kb_user_state/points/delete', body:{filter:{must:[{key:'user_id',match:{value:userId}}]}}, json:true });
    const uuidState='xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&0x3|0x8)).toString(16)});
    await this.helpers.httpRequest({ method:'PUT',url:QDRANT+'/collections/kb_user_state/points', body:{points:[{id:uuidState,vector:Array(1024).fill(0.001),payload:{...state,case_waiting_for:null}}]}, json:true });
  } catch(e) {}

  // set active case in kb_sessions
  try {
    const sessResp = await this.helpers.httpRequest({ method:'POST', url:QDRANT+'/collections/kb_sessions/points/scroll', body:{ limit:1, with_payload:true, filter:{ must:[{ key:'chat_id', match:{ value: chatId } }] } }, json:true });
    let session = sessResp.result?.points?.[0]?.payload || {};
    session.active_case_key = caseName;
    session.chat_id = chatId;
    const uuidSess='xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&0x3|0x8)).toString(16)});
    await this.helpers.httpRequest({ method:'POST', url:QDRANT+'/collections/kb_sessions/points/delete', body:{ filter:{ must:[{ key:'chat_id', match:{ value: chatId } }] } }, json:true });
    await this.helpers.httpRequest({ method:'PUT', url:QDRANT+'/collections/kb_sessions/points', body:{ points:[{ id:uuidSess, vector:Array(1024).fill(0.001), payload:session }] }, json:true });
  } catch(e) {}

  const displayName = caseName.replace(/_/g,' ');
  await this.helpers.httpRequest({ method:'POST', url:BOT+'/sendMessage', json:true, body:{
    chat_id: chatId,
    text:`✅ Створено та активовано кейс: ${displayName}

Оберіть дію в межах кейсу:`,
    reply_markup:{ inline_keyboard:[
    [{ text:'🛡️ DFIR-аналіз (повний звіт)', callback_data:'dfir.start_full_run' }],
    [{ text:'🕒 Хронологія', callback_data:'timeline_case' }, { text:'🧾 Висновок', callback_data:'brief_case' }],
    [{ text:'🌳 Дерево тек (TXT)', callback_data:'tool:fstree' }],
    [{ text:'🔗 IOC кейсу', callback_data:'show_iocs' }, { text:'🌐 Перетин кейсів', callback_data:'case_cross' }],
    [{ text:'➕ Додати IOC (вставити текст)', callback_data:'tool:ioc_add' }],
                    [{ text:'🤖 Згенерувати відповіді', callback_data:'case_qa_run' }, { text:'✅ Що відповідено', callback_data:'case_qa_view' }, { text:'📄 Звіт', callback_data:'case_qa_report' }],
                    [{ text:'🖥 RDP-екран', callback_data:'rdp_screen' }],
    [{ text:'ℹ️ Інфо по кейсу', callback_data:'show_stats' }, { text:'📥 Файли кейсу', callback_data:'files_case' }],
    [{ text:'📦 Завантажити архів зі збирача (ZIP)', callback_data:'up_logs' }],
    [{ text:'📑 Додати PDF-звіт експерта (необовʼязково)', callback_data:'upload_report' }],
    [{ text:'🧠 Завантажити дамп памʼяті (RAM)', callback_data:'up_ram' }],
    [{ text:'📧 Пошта (EML/MSG)', callback_data:'up_email' }],
    [{ text:'🚪 Вийти з кейсу', callback_data:'deactivate_case' }, { text:'🏠 Головне меню', callback_data:'menu_back' }]
  ]}
  }});
  return [];
}

if(caseName.length<2){
  await this.helpers.httpRequest({method:'POST',url:BOT+'/sendMessage',
    body:{chat_id:chatId,text:'❌ Занадто коротка назва. Введіть ще раз:'},json:true});
  return [];
}

// Clear waiting state
const uuid='xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{
  const r=Math.random()*16|0;return(c==='x'?r:(r&0x3|0x8)).toString(16);
});
try {
  await this.helpers.httpRequest({
    method:'POST',url:QDRANT+'/collections/kb_user_state/points/delete',
    body:{filter:{must:[{key:'user_id',match:{value:userId}}]}},json:true
  });
  await this.helpers.httpRequest({
    method:'PUT',url:QDRANT+'/collections/kb_user_state/points',
    body:{points:[{id:uuid,vector:Array(1024).fill(0.001),payload:{
      ...state, kape_waiting_for:null, kape_chosen_case:caseName
    }}]},json:true
  });
} catch(e){}

await this.helpers.httpRequest({method:'POST',url:BOT+'/sendMessage',
  body:{chat_id:chatId,text:`✅ Кейс: "${caseName.replace(/_/g,' ')}"\n⏳ Завантажую файл...`},json:true});

return [{json:{
  chat_id:chatId, user_id:userId,
  file_id:state.kape_file_id,
  file_name:state.kape_file_name||'kape.csv',
  extension:state.kape_extension||'csv',
  doc_type:'kape', collection:'kb_logs',
  case_key:caseName, case_name:caseName
}}];

const CFG = $json.CONFIG || (() => {
  try {
    return $('⚙️ Config').first().json.CONFIG;
  } catch (e) {
    throw new Error('CONFIG_MISSING: ⚙️ Config node required');
  }
})();
if (!CFG || !CFG.BOT) {
  throw new Error('CONFIG_MISSING: CFG.BOT missing');
}

// Process ZIP/CSV uploaded via n8n web form
// Form fields: chat_id (number), case_name (text), file (binary)
const formData = $input.first();
const chatId = parseInt(formData.json?.chat_id || formData.json?.data?.chat_id);
const caseNameRaw = (formData.json?.case_name || formData.json?.data?.case_name || '').trim();
const mode = String(formData.json?.mode || formData.json?.data?.mode || 'kape').toLowerCase();
const userId = parseInt(formData.json?.user_id || chatId);
const BOT = CFG.BOT;
const QDRANT = CFG.QDRANT;

if(!chatId){ throw new Error('chat_id is required'); }

const caseName = caseNameRaw.replace(/[^a-zA-Z0-9а-яА-ЯіІїЇєЄ\s_-]/g,'')
                             .trim().replace(/\s+/g,'_').slice(0,60) || 'kape_upload';

// Get binary data - n8n form stores file in binary
const binary = formData.binary;
const binaryKey = Object.keys(binary||{})[0];
if(!binaryKey){ throw new Error('No file uploaded'); }

const fileInfo = binary[binaryKey];
const fileName = fileInfo.fileName || 'kape.zip';
const ext = fileName.split('.').pop().toLowerCase();
let docType='kape', collection='kb_logs';
if (mode==='report') { docType='report'; collection='kb_reports'; }
else if (mode==='kb' || mode==='docs') { docType='docs'; collection=(($('⚙️ Config').first().json.CONFIG||{}).TEXT_COLL_PRIMARY || 'kb_text_qwen3e8b_v1'); }
else if (mode==='raw') { docType='raw'; collection='kb_logs'; }

await this.helpers.httpRequest({method:'POST',url:BOT+'/sendMessage',
  body:{chat_id:chatId,
