}];

let CFG; try { CFG = $('⚙️ Config').first().json.CONFIG; } catch(e) { throw new Error('CONFIG_MISSING: ⚙️ Config node required'); }

// After all KAPE files saved — run LLM auto-analysis + IOC cross-ref with PDF report
const input = $input.first().json;
const chatId = input.chat_id;
const caseKey = input.case_key;
const BOT = CFG.BOT;
const QDRANT = CFG.QDRANT;
const OLLAMA = CFG.OLLAMA;
const EMBED  = 'bge-m3';

// 1. Get top IOCs from kb_iocs for this case
let logIOCs = [], reportIOCs = [], matchedIOCs = [];
try {
  const iocResp = await this.helpers.httpRequest({
    method:'POST', url:QDRANT+'/collections/kb_iocs/points/scroll',
    body:{limit:200,with_payload:true,
      filter:{must:[{key:'case_key',match:{value:caseKey}}]}},
    json:true
  });
  const allIOCs = iocResp.result?.points||[];
  logIOCs    = allIOCs.filter(p=>p.payload?.source==='kape'||p.payload?.doc_type==='kape');
  reportIOCs = allIOCs.filter(p=>p.payload?.source==='report'||p.payload?.doc_type==='report');

  // Cross-reference: find IOC values appearing in both
  const logVals = new Set(logIOCs.map(p=>p.payload?.value?.toLowerCase()));
  const repVals = new Set(reportIOCs.map(p=>p.payload?.value?.toLowerCase()));
  matchedIOCs = [...logVals].filter(v=>repVals.has(v));
} catch(e){}

// 2. Get sample log chunks for LLM context
let logContext = '';
try {
  const sampleVec = await this.helpers.httpRequest({
    method:'POST', url:OLLAMA+'/v1/embeddings',
    body:{model:EMBED, input:'suspicious activity malware persistence execution'},
    json:true, timeout:30000
  });
  const sampleEmbedding = (sampleVec.data && sampleVec.data[0] && sampleVec.data[0].embedding) ? sampleVec.data[0].embedding : sampleVec.embedding;
  if(Array.isArray(sampleEmbedding)){
    const sr = await this.helpers.httpRequest({
      method:'POST', url:QDRANT+'/collections/kb_logs/points/search',
      body:{vector:sampleEmbedding, limit:8, with_payload:true,
        filter:{must:[{key:'case_key',match:{value:caseKey}}]}},
      json:true, timeout:15000
    });
    logContext = (sr.result||[]).map(r=>r.payload?.text||'').join('\n---\n').slice(0,3000);
  }
} catch(e){}

// 3. LLM analysis
let analysis = '';
if(logContext.length>50){
  try {
    const llmResp = await this.helpers.httpRequest({
      method:'POST', url:CFG.OLLAMA+'/v1/chat/completions',
      body:{
        model: CFG.LLM_STRONG_MODEL,
        messages:[
          {role:'system',content:'Ти DFIR-аналітик. Проаналізуй артефакти KAPE і визнач: 1) Підозрілі процеси/програми 2) Потенційне зловмисне ПЗ 3) Persistence механізми 4) Lateral movement. Відповідай коротко, по пунктах, українською.'},
          {role:'user',content:'KAPE артефакти кейсу "'+caseKey.replace(/_/g,' ')+'":\n\n'+logContext}
        ],
        stream:false, options:{temperature:0.2, num_ctx:4000}
      },
      json:true, timeout:120000
    });
    analysis = llmResp.message?.content||'';
  } catch(e){ analysis='LLM недоступний: '+e.message; }
}

// 4. Send report to Telegram
const iocSummary = input.total_iocs||0;
let msg = `✅ 📋 KAPE оброблено!\n\n`;
msg += `📁 Кейс: ${caseKey.replace(/_/g,' ')}\n`;
msg += `📦 Chunks: ${input.total_chunks||0}\n`;
msg += `🎯 IOC: ${iocSummary}`;

if(matchedIOCs.length>0){
  msg += `\n\n🔥 ЗБІГИ з PDF звітом: ${matchedIOCs.length}\n`;
  msg += matchedIOCs.slice(0,5).map(v=>`  • ${v}`).join('\n');
  if(matchedIOCs.length>5) msg+=`\n  ... та ще ${matchedIOCs.length-5}`;
}

if(analysis){
  msg += `\n\n🤖 Авто-аналіз:\n${analysis.slice(0,800)}`;
}

// Split if too long
const chunks = [];
for(let i=0;i<msg.length;i+=4000) chunks.push(msg.slice(i,i+4000));

for(const chunk of chunks){
  await this.helpers.httpRequest({method:'POST',url:BOT+'/sendMessage',
    body:{chat_id:chatId, text:chunk,
      reply_markup:chunks.indexOf(chunk)===chunks.length-1?{inline_keyboard:[[
        {text:'📁 Відкрити кейс',callback_data:'ci_0'},
        {text:'📊 Статистика',   callback_data:'show_stats'}
      ]]}:undefined
    }, json:true
  });
}

return [{json:{done:true, case_key:caseKey, matched_iocs:matchedIOCs.length}}];

