function addDoc(file, coll, title){
  const d = ensureDoc(file);
  if(!d) return;
  d.chunks += 1;
  d.collections[coll] = true;
  const t = String(title||'').trim();
  if (!t) return;
  let clean = t;
  const m = clean.match(/^(.*?)\s*::\s*.+$/);
  if (m && m[1]) clean = m[1].trim();
  clean = clean.replace(/\s+/g,' ').trim();
  if (clean && clean.toLowerCase() !== String(file).toLowerCase()) {
    d.topics[clean] = (d.topics[clean]||0) + 1;
  }
}

