function topicToUA(t){
  const s = String(t||'').toLowerCase();
  if (s.includes('fullchunks') || s==='reference') return null;
  if (s.includes('incident response')) return 'процес реагування на інциденти';
  if (s.includes('memory forensics')) return 'аналіз пам’яті (RAM)';
  if (s.includes('event logs') || s.includes('evtx')) return 'аналіз журналів подій Windows';
  if (s.includes('mft') || s.includes('$j')) return 'файлова система та артефакти NTFS';
  if (s.includes('prefetch') || s.includes('pecmd')) return 'виконання програм (Prefetch/PECmd)';
  if (s.includes('malware') || s.includes('persistence')) return 'malware та закріплення';
  if (s.includes('lab') || s.includes('tools') || s.includes('csirt')) return 'інструменти, лабораторія та CSIRT';
  if (s.includes('disk') || s.includes('file systems')) return 'диски та файлові системи';
  if (s.includes('foundations')) return 'базові принципи DFIR';
  return null;
}
function inferFromName(file){
  const f = String(file||'').toLowerCase();
  if (f.includes('memory')) return 'аналіз пам’яті (RAM)';
  if (f.includes('incident') || f.includes('response')) return 'реагування на інциденти';
  if (f.includes('forensic') || f.includes('dfir')) return 'практика цифрової криміналістики';
  if (f.includes('kali') || f.includes('tools')) return 'інструменти та лабораторні практики';
  if (f.includes('rootkit') || f.includes('malware')) return 'аналіз шкідливого ПЗ';
  return 'довідник з DFIR/кіберрозслідувань';
}

function emojiByTopic(primary){
  const p = String(primary||'').toLowerCase();
  if (p.includes('реагування на інциденти')) return '🚨';
  if (p.includes('аналіз пам')) return '🧠';
  if (p.includes('журнал')) return '📜';
  if (p.includes('ntfs') || p.includes('файлова система') || p.includes('диски')) return '💽';
  if (p.includes('malware')) return '🦠';
  if (p.includes('csirt') || p.includes('інструменти')) return '🛠';
  if (p.includes('базові принципи')) return '📘';
  return '🔎';
}

function sentence2(primary, file){
  const p = String(primary||'').toLowerCase();
  const f = String(file||'').toLowerCase();
  if (p.includes('реагування на інциденти')) return 'Описує етапи IR: triage, пріоритезацію, ескалацію та підготовку доказової частини звіту.';
  if (p.includes('аналіз пам')) return 'Показує, як шукати ін’єкції, підозрілі процеси, мережеві артефакти та volatile-докази.';
  if (p.includes('журнал')) return 'Дає практику кореляції Event ID, джерел логів і побудови перевірюваного таймлайну.';
  if (p.includes('ntfs') || p.includes('файлова система') || p.includes('диски')) return 'Покриває MFT/USN/$J, часові мітки й реконструкцію дій користувача на хості.';
  if (p.includes('malware')) return 'Фокусується на persistence, ланцюгах запуску, техніках маскування та triage шкідника.';
  if (p.includes('csirt') || p.includes('інструменти')) return 'Містить прикладні утиліти, команди й відтворювані playbook-кроки для польової роботи.';
  if (p.includes('базові принципи')) return 'Пояснює методологію DFIR і як поєднувати різні артефакти в єдину картину інциденту.';
  if (f.includes('nist')) return 'Структурує розслідування за NIST: збір, збереження, аналіз і представлення доказів.';
  if (f.includes('interpol')) return 'Орієнтований на стандарти лабораторної якості та повторюваність результатів експертизи.';
  if (f.includes('cookbook')) return 'Дає покрокові рецепти для типових DFIR-сценаріїв і швидкого застосування в кейсах.';
  return 'Надає практичний контекст застосування знань у реальних інцидентах та розслідуваннях.';
}

function buildDescription(file, mapped){
  const primary = mapped[0] || inferFromName(file);
  const secondary = mapped[1] || null;
  const em = emojiByTopic(primary);
  const s1 = secondary
    ? `${em} Фокус: ${primary} + ${secondary}.`
    : `${em} Фокус: ${primary}.`;
  const s2 = sentence2(primary, file);
  return `${s1} ${s2}`;
}

