function canonCaseKey(v){ return String(v||'').trim().replace(/[\s_]+/g,'_').replace(/^_+|_+$/g,'').toLowerCase(); }
if (action === 'brief_approve') {
  let draftPoints=[];
  let nextOffset=null;
  try {
    for (let _page=0; _page<10; _page++) {
      const body = { limit:100, with_payload:true, with_vector:false,
