}

if (action === 'tl_approve') {
  // Save the newest non-empty generated draft timeline as approved for this case.
  // Qdrant scroll is not sorted, so a small limit can miss the latest draft.
  let draftPoints=[];
  let nextOffset=null;
  try {
    for (let _page=0; _page<10; _page++) {
      const body = { limit:100, with_payload:true, with_vector:false,
        filter:{ must:[{ key:'case_key', match:{ value: activeCase } }, { key:'kind', match:{ value:'timeline_draft' } }] } };
      if (nextOffset) body.offset = nextOffset;
      const r = await this.helpers.httpRequest({ method:'POST', url: QDRANT + '/collections/kb_cases/points/scroll', json:true, body });
      const pts = r?.result?.points || [];
      draftPoints.push(...pts);
      nextOffset = r?.result?.next_page_offset || null;
      if (!nextOffset || !pts.length) break;
    }
  } catch(e) { console.error('timeline approve draft scroll:', String(e?.message||e)); }
  draftPoints = draftPoints.filter(p => String((p.payload||{}).timeline_text || '').trim().length > 0);
  if (!draftPoints.length) {
    await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true, body:{ chat_id:chatId, text:'⚠️ Немає згенерованої чернетки хронології для фіксації. Спочатку натисніть «🕒 Хронологія».' } });
    return [{json:{done:true,no_draft:true}}];
  }
  const scoreDraft = (p) => {
    const d = p.payload || {};
    const t = Date.parse(String(d.generated_at || d.approved_at || '')) || 0;
    const len = String(d.timeline_text || '').length;
    return {t, len, id:String(p.id||'')};
  };
  draftPoints.sort((a,b)=>{
    const A=scoreDraft(a), B=scoreDraft(b);
    if (B.t !== A.t) return B.t - A.t;
    if (B.len !== A.len) return B.len - A.len;
    return B.id.localeCompare(A.id);
  });
  const d = draftPoints[0].payload || {};
  const uuid='xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&0x3|0x8)).toString(16)});
  try {
    await this.helpers.httpRequest({ method:'PUT', url:QDRANT+'/collections/kb_cases/points', json:true,
      body:{ points:[{ id:uuid, vector:Array(4096).fill(0.001), payload:{
        case_key: activeCase,
        kind: 'timeline_approved',
        timeline_text: String(d.timeline_text||''),
        timeline_events_count: Number(d.timeline_events_count||0),
        timeline_parts_count: Number(d.timeline_parts_count||0),
        source_reports: d.source_reports || [],
        generated_from: String(d.generated_from || 'logs'),
        approved_at: new Date().toISOString(),
        approved_by_chat_id: chatId
      }}] }
    });
  } catch(e) {
    await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true, body:{ chat_id:chatId, text:'❌ Не вдалося зафіксувати хронологію. Спробуйте ще раз.' } });
    return [{json:{done:true,approve_error:true}}];
  }
  await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true, body:{
    chat_id:chatId,
    text:'✅ Хронологію зафіксовано для цього кейсу. Наступні відкриття «🕒 Хронологія» показуватимуть збережену версію.',
    reply_markup:{ inline_keyboard:[
    [{ text:'🛡️ DFIR-аналіз (повний звіт)', callback_data:'dfir.start_full_run' }],
    [{ text:'🕒 Хронологія', callback_data:'timeline_case' }, { text:'🧾 Висновок', callback_data:'brief_case' }],
    [{ text:'🌳 Дерево тек (TXT)', callback_data:'tool:fstree' }],
    [{ text:'🔗 IOC кейсу', callback_data:'show_iocs' }, { text:'🌐 Перетин кейсів', callback_data:'case_cross' }],
    [{ text:'➕ Додати IOC (вставити текст)', callback_data:'tool:ioc_add' }],
                    [{ text:'🤖 Згенерувати відповіді', callback_data:'case_qa_run' }, { text:'✅ Що відповідено', callback_data:'case_qa_view' }, { text:'📄 Звіт', callback_data:'case_qa_report' }],
                    [{ text:'🖥 RDP-екран', callback_data:'rdp_screen' }],
    [{ text:'ℹ️ Інфо по кейсу', callback_data:'show_stats' }, { text:'📥 Файли кейсу', callback_data:'files_case' }],
    [{ text:'📦 Завантажити архів зі збирача (ZIP)', callback_data:'up_logs' }],
    [{ text:'📑 Додати PDF-звіт експерта (необовʼязково)', callback_data:'upload_report' }],
    [{ text:'🧠 Завантажити дамп памʼяті (RAM)', callback_data:'up_ram' }],
    [{ text:'📧 Пошта (EML/MSG)', callback_data:'up_email' }],
    [{ text:'🚪 Вийти з кейсу', callback_data:'deactivate_case' }, { text:'🏠 Головне меню', callback_data:'menu_back' }]
  ] }
  }});
  return [{json:{done:true,approved:true,case_key:activeCase}}];
}

if (action === 'timeline_case' || action === 'tl_regen') {
  const forceRegen = (action === 'tl_regen');

  function splitText(text, head='') {
    const chunks=[];
    let cur=head ? (head + '\n\n') : '';
    const lines=String(text||'').split('\n');
    for (const ln of lines) {
      const line=ln+'\n';
      if ((cur + line).length > 3600) { chunks.push(cur); cur=''; }
      cur += line;
    }
    if (cur.trim()) chunks.push(cur);
    return chunks;
  }

  if (!forceRegen) {
    let approved=[];
    try {
      const ar = await this.helpers.httpRequest({ method:'POST', url: QDRANT + '/collections/kb_cases/points/scroll', json:true,
        body:{ limit:20, with_payload:true, with_vector:false, filter:{ must:[{ key:'case_key', match:{ value: activeCase } }, { key:'kind', match:{ value:'timeline_approved' } }] } }
      });
      approved = ar?.result?.points || [];
    } catch(e) {}
    if (approved.length) {
      approved.sort((a,b)=>String((b.payload||{}).approved_at||'').localeCompare(String((a.payload||{}).approved_at||'')));
      const ap = approved[0].payload || {};
      const txt = String(ap.timeline_text || '').trim();
      if (txt) {
        const _genFrom = String(ap.generated_from || '');
        const _warn = (_genFrom === 'sql_fallback' || _genFrom === 'sql_fallback_invalidated') ? '\n⚠️ Це структурована хронологія за зібраними артефактами. Її можна перегенерувати для повторної аналітичної перевірки.' : (_genFrom && _genFrom !== 'logs') ? '\n⚠️ Це збережена версія. За потреби натисніть «Генерувати повторно» для перевірки за актуальними артефактами.' : '';
        const parts = splitText(txt, `🕒 Зафіксована хронологія: ${String(activeCase).replace(/_/g,' ')}`);
        for (let i=0;i<parts.length;i++) {
          const t = (i===0) ? parts[i] : `🕒 Продовження (${i+1}/${parts.length})\n\n` + parts[i];
          await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true, body:{ chat_id:chatId, text:t } });
        }
        await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true, body:{
          chat_id:chatId,
          text:(`✅ Показано зафіксовану версію. Подій: ${Number(ap.timeline_events_count||0)}.${_warn}`),
          reply_markup:{ inline_keyboard:[[{text:'🔁 Генерувати повторно',callback_data:'tl_regen'}],[{text:'⬅️ До кейсу',callback_data:'case_menu'}]] }
        }});
        return [{json:{done:true,from_cache:true,case_key:activeCase}}];
      }
    }
  }

  const _tlLockKey = `tl_lock_${chatId}`;
  const _sdTl = $getWorkflowStaticData('global');
  const _tlNow = Date.now();
  if (_sdTl[_tlLockKey] && (_tlNow - _sdTl[_tlLockKey]) < 1800000) {
    await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true,
      body:{ chat_id:chatId, text:'⏳ Хронологія вже генерується для цього чату. Зачекайте або спробуйте через 30 хвилин.' } });
    return [{json:{done:true,tl_locked:true}}];
  }
  _sdTl[_tlLockKey] = _tlNow;

  let _tlProgId = null;
  try {
    const _ps = await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true,
      body:{ chat_id:chatId, text:'⏳ Будую хронологію з логів... (10%)' } });
    _tlProgId = _ps?.result?.message_id || null;
  } catch(e) {}
  const _editTl = async (t) => {
    if (!_tlProgId) return;
    try { await this.helpers.httpRequest({ method:'POST', url: BOT + '/editMessageText', json:true,
      body:{ chat_id:chatId, message_id:_tlProgId, text:t } }); } catch(e) {}
  };

  try {
    await _editTl('⏳ Збираю події зі зібраних артефактів... (25%)');
    let _pyTl = null, _pyTlMeta = {};
    try {
      const _pyR = await this.helpers.httpRequest({
        method:'POST', url:'http://case-maintainer:8787/generate-timeline', json:true,
        body:{ case_key: activeCase, force_regen: forceRegen, background: forceRegen, chat_id: chatId, progress_message_id: _tlProgId }, timeout: Number(forceRegen ? 30000 : (CFG.LLM_BRIEF_TIMEOUT || 300000))
      });
      if (_pyR?.ok && _pyR?.queued) {
        await _editTl(String(_pyR.timeline_text || '🕒 Генерація хронології\n\n▓▓░░░░░░░░░░░░░░ 12%\n⚙️ Починаю побудову хронології'));
        delete _sdTl[_tlLockKey];
        return [{json:{done:true, tl_background_queued:true, case_key:activeCase, job_id:_pyR.job_id||null}}];
      }
      if (_pyR?.ok && _pyR?.timeline_text) {
        _pyTl = String(_pyR.timeline_text);
        _pyTlMeta = { events: _pyR.timeline_events_count || 0, source: _pyR.source || 'logs' };
      }
    } catch(e) { console.error('generate-timeline:', String(e?.message||e)); }

    if (_tlProgId) { try { await this.helpers.httpRequest({method:'POST',url:BOT+'/deleteMessage',json:true,body:{chat_id:chatId,message_id:_tlProgId}}); } catch(e) {} _tlProgId=null; }

    if (!_pyTl) {
      await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true, body:{
        chat_id:chatId, text:'⚠️ Не вдалося побудувати хронологію. Спробуйте ще раз.',
        reply_markup:{ inline_keyboard:[[{text:'🔁 Спробувати знову',callback_data:'tl_regen'}],[{text:'⬅️ До кейсу',callback_data:'case_menu'}]] }
      }});
      return [{json:{done:true, empty_timeline:true, case_key:activeCase}}];
    }

    const tlChunks = splitText(_pyTl, `🕒 Хронологія (логи): ${String(activeCase).replace(/_/g,' ')}`);
    for (let i=0;i<tlChunks.length;i++) {
      const t = (i===0) ? tlChunks[i] : `🕒 Продовження (${i+1}/${tlChunks.length})\n\n` + tlChunks[i];
      await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true, body:{ chat_id:chatId, text:t } });
    }
    await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true, body:{
      chat_id:chatId,
      text:`✅ Хронологію побудовано. Подій: ${_pyTlMeta.events||0}.`,
      reply_markup:{ inline_keyboard:[[{text:'✅ Зафіксувати результат',callback_data:'tl_approve'},{text:'🔁 Генерувати повторно',callback_data:'tl_regen'}],[{text:'⬅️ До кейсу',callback_data:'case_menu'}]] }
    }});
    return [{json:{done:true, tl_from_logs:true, case_key:activeCase, events:_pyTlMeta.events||0}}];

  } catch(_e) {
    console.error('timeline error:', String(_e?.message||_e));
    if (_tlProgId) { try { await this.helpers.httpRequest({method:'POST',url:BOT+'/deleteMessage',json:true,body:{chat_id:chatId,message_id:_tlProgId}}); } catch(e) {} }
  } finally {
    delete _sdTl[_tlLockKey];
  }
}

// files library mode
if (action === 'files_case') {
