    return [{json:{done:true, empty_files:true, case_key:activeCase}}];
  }

  points = points.sort((a,b)=>String((b.payload||{}).ts||'').localeCompare(String((a.payload||{}).ts||'')));
  const kb=[];
  let text=`📥 Файли кейсу: ${String(activeCase).replace(/_/g,' ')}\n\n`;
  for (const p of points.slice(0,30)) {
