    const ext = (fullName.match(/\.[A-Za-z0-9]{1,8}$/)||[''])[0];
    let nm = fullName;
    if (nm.length > 46) {
      const head = nm.slice(0, 28);
      const tail = nm.slice(-12);
      nm = head + '…' + tail;
    }
    const mode=String(pl.mode||'misc');
    const up=String(pl.upload_id||'');
