  kb.push([{text:'⬅️ До кейсу', callback_data:'case_menu'}]);
  await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true, body:{ chat_id:chatId, text, reply_markup:{ inline_keyboard: kb } } });
  return [{json:{done:true, files:points.length, case_key:activeCase}}];
