if (action === 'process_tree_case') {
  if (!activeCase) {
    await this.helpers.httpRequest({ method:'POST', url:BOT+'/sendMessage', json:true,
      body:{ chat_id:chatId, text:'❌ Немає активного кейсу.' } });
    return [{json:{done:true}}];
  }
  let progId = null;
  try {
    const s = await this.helpers.httpRequest({method:'POST',url:BOT+'/sendMessage',json:true,
      body:{chat_id:chatId,text:'⏳ Будую дерево процесів...'}});
    progId = s?.result?.message_id || null;
  } catch(e){}
  try {
    const pr = await this.helpers.httpRequest({
      method:'GET',
      url:'http://case-maintainer:8787/process-tree?case_key='+encodeURIComponent(activeCase)+'&limit=150',
      json:true, timeout:20000
    });
    if (!pr?.ok || !pr?.nodes?.length) {
      const t = '❌ Даних процесів (EID 4688) для цього кейсу не знайдено.';
      if (progId) { await this.helpers.httpRequest({method:'POST',url:BOT+'/editMessageText',json:true,body:{chat_id:chatId,message_id:progId,text:t}}); }
      else { await this.helpers.httpRequest({method:'POST',url:BOT+'/sendMessage',json:true,body:{chat_id:chatId,text:t}}); }
      return [{json:{done:true,no_data:true}}];
    }
    const nodes = pr.nodes;
    // Filter: skip pure boot noise (smss-only chains)
    const noisyChildren = new Set(['registry','ntoskrnl.exe','ntdll.dll']);
    const SYSTEM_PARENTS = new Set(['','smss.exe','wininit.exe','services.exe','csrss.exe','svchost.exe','explorer.exe']);
    const suspicious = nodes.filter(n => {
      const child = (n.child||'').toLowerCase().trim();
      const parent = (n.parent||'').toLowerCase().trim();
      if (noisyChildren.has(child)) return false;
      if (!SYSTEM_PARENTS.has(parent)) return true;
      // child launched by suspicious parent or child itself is suspicious
      return /cmd|powershell|wscript|cscript|rundll|regsvr|mshta|python|7z|rar|rutserv|rfusclient|ngrok|system32\.exe|litemanager|anydesk/.test(child);
    });
    const display = (suspicious.length > 0 ? suspicious : nodes).slice(0,30);
    const caseShort = String(activeCase||'').replace(/_/g,' ').slice(0,40);
    let lines = [`🌳 Дерево процесів: ${caseShort}`, `Всього EID 4688 записів: ${nodes.length}`, ''];
    if (suspicious.length > 0) lines.push(`⚠️ Підозрілих ланцюжків: ${suspicious.length}`, '');
    // Group by parent
    const byParent = {};
    for (const n of display) {
      const p = n.parent || '(система)';
      (byParent[p] = byParent[p]||[]).push(n);
    }
    for (const [parent, children] of Object.entries(byParent)) {
      lines.push(`📂 ${parent}`);
      for (const n of children.slice(0,6)) {
        lines.push(`   └─ ${n.child} [${n.ts.slice(5,16)}]`);
      }
      if (children.length > 6) lines.push(`   └─ ... ще ${children.length-6}`);
      lines.push('');
    }
    const txt = lines.join('\n').slice(0,4000);
    const kb = {inline_keyboard:[[{text:'🔁 Оновити',callback_data:'process_tree_case'},{text:'⬅️ До кейсу',callback_data:'case_menu'}]]};
    if (progId) {
      await this.helpers.httpRequest({method:'POST',url:BOT+'/editMessageText',json:true,body:{chat_id:chatId,message_id:progId,text:txt,reply_markup:kb}});
    } else {
      await this.helpers.httpRequest({method:'POST',url:BOT+'/sendMessage',json:true,body:{chat_id:chatId,text:txt,reply_markup:kb}});
    }
  } catch(e) {
    const errMsg = '❌ Помилка при отриманні process tree: ' + String(e?.message||e).slice(0,100);
    if (progId) { try { await this.helpers.httpRequest({method:'POST',url:BOT+'/editMessageText',json:true,body:{chat_id:chatId,message_id:progId,text:errMsg}}); } catch(_){} }
    else { await this.helpers.httpRequest({method:'POST',url:BOT+'/sendMessage',json:true,body:{chat_id:chatId,text:errMsg}}); }
  }
  return [{json:{done:true,case_key:activeCase}}];
}


