  let url = String(p.url || '');
  try {
    const cfg = await this.helpers.httpRequest({
      method: 'GET', url: 'http://case-maintainer:8787/config/public-base', json: true });
    const viewBase = String(cfg?.view || '').replace(/\/$/, '');
    const ck = String(p.case_key || activeCaseKey || '');
    if (viewBase && ck && fname) {
      url = `${viewBase}/${encodeURIComponent(ck)}/uploads/${encodeURIComponent(fmode)}/${encodeURIComponent(fname)}`;
    }
  } catch (e) { /* keep the stored value if the config cannot be reached */ }

  let msg = `📥 Файл кейсу
📄 ${fname}
🧭 Тип: ${fmode}`;
  if (fsizeMb) msg += `
📦 Розмір: ${fsizeMb} MB`;
  await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true, body:{ chat_id:chatId, text: msg } });
