function fmtTs(v){
  if(!v) return '—';
  const d = new Date(v);
  if (isNaN(d.getTime())) return '—';
  const parts = new Intl.DateTimeFormat('sv-SE', { timeZone:'Europe/Kyiv', year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit', second:'2-digit', hour12:false }).formatToParts(d);
  const m={}; for(const p of parts){ if(p.type!=='literal') m[p.type]=p.value; }
  return (m.year+'-'+m.month+'-'+m.day+' '+m.hour+':'+m.minute+':'+m.second+' Europe/Kiev');
}

