function splitText(s, max=3800){
  const out=[]; let t=String(s||'');
  while(t.length>max){
    let i=t.lastIndexOf('\n', max);
    if(i<max*0.6) i=max;
    out.push(t.slice(0,i));
    t=t.slice(i).replace(/^\n+/, '');
  }
  if(t) out.push(t);
  return out.length?out:[''];
}

