async function startMode(mode){
  const ctx=getCtx();
  const courseId=ctx.course_id||'COURSE';
  const all=await bankAll(courseId);
  if(!all.length){ await send('❌ У цьому курсі поки немає питань. Додай через кнопку "Додати нові питання".',[[{text:'➕ Додати нові питання',callback_data:'study_add_questions'}],[{text:'⬅️ До курсів',callback_data:'study_menu'}]]); return; }
  const size = (mode==='exam') ? Math.min(85, all.length) : Math.min(30, all.length);
  const picked = shuffle(all.map(x=>x.id)).slice(0,size);
  const bank_map={}; all.forEach(q=>bank_map[String(q.id)]={q_en:q.q_en,q_uk:q.q_uk,options:q.options,correct:q.correct,exp_en:q.exp_en,exp_uk:q.exp_uk,tag:q.tag});
  store[sessKey()]={active:true,course_id:courseId,mode,question_ids:picked,current_index:0,answers:{},bank_map};
