async function renderQuestion(){
  const s=store[sessKey()]||{};
  const idx=s.current_index||0; const qid=s.question_ids?.[idx];
  if(qid==null) return finish();
  const q=s.bank_map[String(qid)];
  const n=idx+1,total=s.question_ids.length;
  let t=`🎓 ${s.mode.toUpperCase()}\nПитання ${n}/${total}\n\n${q.q_en}\n\n🇺🇦 ${q.q_uk}\n\n`;
  ['A','B','C','D'].forEach((L,i)=>{ const o=q.options[i]||{}; t+=`${L}) ${o.en||''}\n   ${o.uk||''}\n`; });
  await send(t,[[{text:'A',callback_data:'study_ans_0'},{text:'B',callback_data:'study_ans_1'},{text:'C',callback_data:'study_ans_2'},{text:'D',callback_data:'study_ans_3'}],[{text:'❌ Вийти',callback_data:'study_exit'}]]);
}

async function finish(){
  const s=store[sessKey()]||{}; const total=s.question_ids?.length||0;
  let ok=0, wrong=[];
  for(const qid of (s.question_ids||[])){
    const q=s.bank_map[String(qid)]; const a=(s.answers||{})[String(qid)];
    if(a===q.correct) ok++; else wrong.push({q,a});
  }
  const pct=Math.round((ok/Math.max(1,total))*100);
  let txt=`🏁 Завершено\nРежим: ${s.mode}\nРезультат: ${ok}/${total} (${pct}%)`;
  if(wrong.length){ txt += `\n\nПомилки: ${wrong.length}`; }
  store[sessKey()]={active:false};
  await send(txt,[[{text:'🔁 Ще раз',callback_data:'study_mode_'+(s.mode||'practice')}],[{text:'⬅️ До курсу',callback_data:'study_course_'+(s.course_id||'COURSE')}]]);
}

