  [{ text:'📚 База знань', callback_data:'kb_menu' }, { text:'🧰 Додаткові інструменти', callback_data:'addtools_menu' }],
  [{ text:'🔓 Чат ШІ', callback_data:'tool:free_chat' }],
    [{ text:'📁 Мої кейси', callback_data:'my_cases_menu' }, { text:'📊 Статистика', callback_data:'show_stats' }],
  [{ text:'🔗 Перетин IOC', callback_data:'cross_reports' }, { text:'🚪 Вийти в пошук', callback_data:'global_search' }],
  [{ text:'🛠 Адміністрування', callback_data:'admin_monitor' }, { text:'❓ Допомога', callback_data:'tool:help' }]
];
try { await req('POST', BOT + '/sendMessage', { chat_id:chatId, text, reply_markup:{ inline_keyboard: rows } }); } catch(e) { console.log('[UnknownAction] sendMessage failed: ' + (e && e.message)); }
return [{ json:{ done:true, unknown_action: rawAction, active_case_key: activeCase || null } }];

// QUICK WIN #3: non-text media guard. Reached from AddTools Gate Photo when the
// message was NOT consumed by an addtools flow (photo/voice/sticker/video/etc).
// Replies guidance instead of silence.
let CFG; try { CFG = $('⚙️ Config').first().json.CONFIG; } catch(e) { throw new Error('CONFIG_MISSING: Config node required'); }
const BOT = CFG.BOT;
const m = (($('Telegram Trigger').first().json) || {}).message || {};
const chatId = m.chat && m.chat.id;
if (!chatId) { return [{ json:{ done:false, reason:'no_chat_id' } }]; }
const text = '📎 Я приймаю текст, файли PDF/CSV/ZIP або меню.';
const rows = [[{ text:'☰ Меню', callback_data:'menu_back' }]];
try {
  await this.helpers.httpRequest({ method:'POST', url: BOT + '/sendMessage', json:true, timeout:12000, body:{ chat_id:chatId, text, reply_markup:{ inline_keyboard: rows } } });
} catch(e) { console.log('[MediaGuard] sendMessage failed: ' + (e && e.message)); }
return [{ json:{ done:true, guarded:true } }];
